async function uploadAdImage(imageUrl) {
  let base64;
  if (imageUrl.startsWith("data:")) {
    base64 = imageUrl.split(",")[1] || "";
    if (!base64) throw new Error("Data URL inv\xE1lida");
  } else {
    const imgRes = await fetch(imageUrl);
    if (!imgRes.ok) throw new Error(`N\xE3o foi poss\xEDvel baixar a imagem: ${imgRes.status}`);
    const buffer = await imgRes.arrayBuffer();
    base64 = Buffer.from(buffer).toString("base64");
  }
  const data = await metaPost2(`${AD_ACCOUNT_ID}/adimages`, {
    bytes: base64
  });
  const images = data.images || {};
  const firstKey = Object.keys(images)[0];
  const imageHash = images[firstKey]?.hash;
  if (!imageHash) throw new Error("Upload de imagem falhou \u2014 hash n\xE3o retornado");
  return imageHash;
}
