async function executeMetaAction(actionType, payload) {
  if (!META_TOKEN) throw new Error("META_ACCESS_TOKEN n\xE3o configurado no servidor");
  switch (actionType) {
    case "meta_pause_campaign":
      if (!payload.campaignId) throw new Error("campaignId obrigat\xF3rio");
      await pauseCampaign2(payload.campaignId);
      return `Campanha "${payload.campaignName || payload.campaignId}" pausada com sucesso.`;
    case "meta_resume_campaign":
      if (!payload.campaignId) throw new Error("campaignId obrigat\xF3rio");
      await resumeCampaign2(payload.campaignId);
      return `Campanha "${payload.campaignName || payload.campaignId}" reativada.`;
    case "meta_update_budget": {
      const budget = payload.newDailyBudget || payload.dailyBudgetReais;
      if (!payload.campaignId || !budget) throw new Error("campaignId e dailyBudgetReais obrigat\xF3rios");
      await updateCampaignBudget2(payload.campaignId, budget);
      return `Or\xE7amento de "${payload.campaignName || payload.campaignId}" atualizado para R$${budget}/dia.`;
    }
    case "meta_create_campaign":
      if (!payload.name || !payload.objective || !payload.dailyBudgetReais) throw new Error("name, objective e dailyBudgetReais obrigat\xF3rios");
      const newId = await createCampaign(payload.name, payload.objective, payload.dailyBudgetReais);
      return `Campanha "${payload.name}" criada (ID: ${newId}). Status: PAUSADA \u2014 ative no Meta Ads Manager ap\xF3s revisar.`;
    case "meta_duplicate_campaign":
      if (!payload.campaignId || !payload.name) throw new Error("campaignId e name obrigat\xF3rios");
      const copyId = await duplicateCampaign2(payload.campaignId, payload.name);
      return `Campanha duplicada: "${payload.name}" (ID: ${copyId}). Status: PAUSADA.`;
    case "meta_upload_image":
      if (!payload.imageUrl) throw new Error("imageUrl obrigat\xF3rio");
      const hash = await uploadAdImage(payload.imageUrl);
      return `Imagem enviada com sucesso. Hash: ${hash}`;
    case "meta_create_full_ad":
      if (!payload.campaignId || !payload.adSetId || !payload.imageUrl || !payload.body || !payload.title) {
        throw new Error("campaignId, adSetId, imageUrl, title e body s\xE3o obrigat\xF3rios");
      }
      const adResult = await createFullAd({
        campaignId: payload.campaignId,
        adSetId: payload.adSetId,
        adName: payload.adName || payload.title || "Novo an\xFAncio",
        imageUrl: payload.imageUrl,
        title: payload.title,
        body: payload.body,
        linkUrl: payload.linkUrl || "https://www.feminnita.com.br",
        callToAction: payload.callToAction
      });
      return `An\xFAncio criado com sucesso (pausado para revis\xE3o). ID: ${adResult.adId}`;
    default:
      throw new Error(`Tipo de a\xE7\xE3o Meta desconhecido: ${actionType}`);
  }
}
