async function getDriveAccessToken() {
  if (cachedToken && Date.now() < cachedToken.expiresAt - 3e4) {
    return cachedToken.value;
  }
  const refreshToken = process.env.GOOGLE_DRIVE_REFRESH_TOKEN;
  const clientId = process.env.GOOGLE_OAUTH_CLIENT_ID;
  const clientSecret = process.env.GOOGLE_OAUTH_CLIENT_SECRET;
  if (!refreshToken || !clientId || !clientSecret) return null;
  try {
    const res = await fetch(GOOGLE_TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        refresh_token: refreshToken,
        client_id: clientId,
        client_secret: clientSecret,
        grant_type: "refresh_token"
      })
    });
    const data = await res.json();
    if (!data.access_token) return null;
    cachedToken = { value: data.access_token, expiresAt: Date.now() + (data.expires_in || 3600) * 1e3 };
    return cachedToken.value;
  } catch {
    return null;
  }
}
async function listFolderFiles(folderId) {
  const token = await getDriveAccessToken();
  if (!token) return [];
  try {
    const params = new URLSearchParams({
      q: `'${folderId}' in parents and trashed = false`,
      fields: "files(id,name,mimeType,size,modifiedTime,webViewLink)",
      orderBy: "modifiedTime desc",
      pageSize: "50"
    });
    const res = await fetch(`${DRIVE_API}/files?${params}`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    const data = await res.json();
    return data.files || [];
  } catch {
    return [];
  }
}
async function downloadFileAsBase64(fileId) {
  const token = await getDriveAccessToken();
  if (!token) return null;
  try {
    const metaRes = await fetch(`${DRIVE_API}/files/${fileId}?fields=mimeType,name`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    const meta = await metaRes.json();
    const mimeType = meta.mimeType || "image/jpeg";
    const res = await fetch(`${DRIVE_DOWNLOAD}/${fileId}?alt=media`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    if (!res.ok) return null;
    const buffer = await res.arrayBuffer();
    const base64 = Buffer.from(buffer).toString("base64");
    return { base64, mimeType };
  } catch {
    return null;
  }
}
function isDriveConfigured() {
  return !!(process.env.GOOGLE_DRIVE_REFRESH_TOKEN && process.env.GOOGLE_OAUTH_CLIENT_ID && process.env.GOOGLE_OAUTH_CLIENT_SECRET);
}
