async function listDriveReferenceFiles() {
  if (!isDriveConfigured()) return [];
  const result = [];
  for (const [label, folderId] of [
    ["Artes Prontas", ARTES_ADS_FOLDER],
    ["Refer\xEAncias", DEFAULT_REFERENCE_FOLDER]
  ]) {
    if (!folderId) continue;
    const files = await listFolderFiles(folderId);
    for (const f of files.filter((f2) => f2.mimeType.startsWith("image/"))) {
      result.push({ id: f.id, name: f.name, folder: label });
    }
  }
  return result;
}
