init_shopeeApi();
import crypto3 from "crypto";
import fs4 from "fs";
import path4 from "path";
var PARTNER_ID2 = parseInt(process.env.SHOPEE_PARTNER_ID || "0");
var PARTNER_KEY2 = process.env.SHOPEE_PARTNER_KEY || "";
var BASE_URL2 = "https://partner.shopeemobile.com";
function updateEnvFile2(updates) {
  const envPath = path4.resolve(process.cwd(), ".env");
  let content = "";
  try {
    content = fs4.readFileSync(envPath, "utf-8");
  } catch {
  }
  for (const [key, value] of Object.entries(updates)) {
    const regex = new RegExp(`^${key}=.*$`, "m");
    if (regex.test(content)) {
      content = content.replace(regex, `${key}=${value}`);
    } else {
      content += `
${key}=${value}`;
    }
    process.env[key] = value;
  }
  fs4.writeFileSync(envPath, content, "utf-8");
}
async function refreshShopeeToken() {
  const refreshToken = process.env.SHOPEE_REFRESH_TOKEN || "";
  const shopId = parseInt(process.env.SHOPEE_SHOP_ID || "0");
  if (!refreshToken || !shopId) {
    console.warn("[ShopeeOAuth] refresh imposs\xEDvel \u2014 token ou shopId ausente");
    return false;
  }
  try {
    const apiPath = "/api/v2/auth/access_token/get";
    const ts = Math.floor(Date.now() / 1e3);
    const sign = shopeeSign(apiPath, ts);
    const url = `${BASE_URL2}${apiPath}?partner_id=${PARTNER_ID2}&timestamp=${ts}&sign=${sign}`;
    const r = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ refresh_token: refreshToken, shop_id: shopId, partner_id: PARTNER_ID2 })
    });
    const data = await r.json();
    if (data.access_token) {
      updateEnvFile2({ SHOPEE_ACCESS_TOKEN: data.access_token, SHOPEE_REFRESH_TOKEN: data.refresh_token || refreshToken });
      console.log("[ShopeeOAuth] \u2705 Token renovado automaticamente");
      return true;
    }
    console.warn("[ShopeeOAuth] Refresh falhou:", JSON.stringify(data));
    return false;
  } catch (e) {
    console.error("[ShopeeOAuth] Erro ao renovar token:", e.message);
    return false;
  }
}
