async function fetchTrayPage(url) {
  try {
    const res = await fetch(url, {
      headers: { "User-Agent": "Mozilla/5.0 (compatible; FeminnitaBot/1.0)" },
      signal: AbortSignal.timeout(1e4)
    });
    if (!res.ok) return `[HTTP ${res.status}]`;
    const html = await res.text();
    const title = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1]?.replace(/<[^>]+>/g, "").trim() || "";
    const h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i)?.[1]?.replace(/<[^>]+>/g, "").trim() || "";
    const prices = [...html.matchAll(/R\$\s*[\d.,]+/g)].map((m2) => m2[0]).slice(0, 4);
    const canonical = html.match(/<link[^>]*rel=["']canonical["'][^>]*href=["']([^"']+)["']/i)?.[1] || url;
    const productLinks = [];
    const linkRe = /href=["'](https?:\/\/www\.feminnita\.com\.br\/[^"'?#]+)["'][^>]*>/gi;
    let m;
    while ((m = linkRe.exec(html)) !== null) {
      const l = m[1];
      if (!productLinks.includes(l) && !l.includes("/busca") && l.split("/").length >= 4) {
        productLinks.push(l);
      }
    }
    const text3 = html.replace(/<script[\s\S]*?<\/script>/gi, "").replace(/<style[\s\S]*?<\/style>/gi, "").replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ").replace(/\s+/g, " ").trim().slice(0, 2500);
    return [
      `URL: ${canonical}`,
      title ? `T\xCDTULO: ${title}` : "",
      h1 ? `H1: ${h1}` : "",
      prices.length ? `PRE\xC7OS: ${prices.join(" | ")}` : "",
      productLinks.length ? `LINKS DE PRODUTOS:
${productLinks.slice(0, 12).join("\n")}` : "",
      `CONTE\xDADO: ${text3}`
    ].filter(Boolean).join("\n");
  } catch (e) {
    return `[Erro ao acessar ${url}: ${e.message}]`;
  }
}
async function searchTrayProducts(query) {
  const searchUrl = `${LOJA_URL}/busca?q=${encodeURIComponent(query)}`;
  return fetchTrayPage(searchUrl);
}
