async function runWhatsAppFunnelAgent(phoneNumber, contactName, incomingMessage, userId = 1) {
  const db = await getDb();
  if (!isBusinessHours()) {
    const msg = outOfHoursMessage(contactName);
    if (db) {
      await db.insert(conversationHistory).values({
        userId,
        whatsappPhoneNumber: phoneNumber,
        whatsappContactName: contactName || null,
        userMessage: incomingMessage,
        aiResponse: msg,
        confidence: "1.00",
        escalated: false,
        status: "out_of_hours"
      }).catch(() => null);
    }
    console.log(`[WA Lia] Fora do expediente \u2014 ${phoneNumber}`);
    return msg;
  }
  if (needsEscalation(incomingMessage)) {
    const msg = "Vou chamar nossa equipe para te ajudar com isso! Um momento \u{1F60A}";
    if (db) {
      await db.insert(conversationHistory).values({
        userId,
        whatsappPhoneNumber: phoneNumber,
        whatsappContactName: contactName || null,
        userMessage: incomingMessage,
        aiResponse: msg,
        confidence: "1.00",
        escalated: true,
        status: "escalated"
      }).catch(() => null);
    }
    notifyTeamEscalation(phoneNumber, contactName, incomingMessage);
    console.log(`[WA Lia] Escala\xE7\xE3o: ${phoneNumber} \u2014 "${incomingMessage.slice(0, 60)}"`);
    return msg;
  }
  const history = db ? await db.select().from(conversationHistory).where(and6(
    eq8(conversationHistory.userId, userId),
    eq8(conversationHistory.whatsappPhoneNumber, phoneNumber)
  )).orderBy(desc3(conversationHistory.id)).limit(8) : [];
  const messages = history.reverse().flatMap((h) => [
    { role: "user", content: h.userMessage },
    ...h.aiResponse ? [{ role: "assistant", content: h.aiResponse }] : []
  ]);
  messages.push({ role: "user", content: incomingMessage });
  const nameCtx = contactName ? `
Cliente atual: ${contactName}` : "";
  const cartCtx = cartContextStore.get(phoneNumber);
  const cartNote = cartCtx ? `

\u2501\u2501\u2501 CONTEXTO: CARRINHO ABANDONADO \u2501\u2501\u2501
Esta cliente estava recuperando um carrinho. Use isso para retomar a conversa de forma natural.
Itens no carrinho:
${cartCtx.items.map((i) => `\u2022 ${i.name}${i.price ? ` \u2014 ${i.price}` : ""}${i.url ? ` (${i.url})` : ""}`).join("\n")}
Valor total: R$${cartCtx.cartValue.toFixed(2)}
Segmento: ${cartCtx.isB2B ? "B2B (atacado)" : "B2C (varejo)"}
` + (cartCtx.cartUrl ? `Link do carrinho: ${cartCtx.cartUrl}
` : "") + `Abordagem: mencione os produtos do carrinho dela, ofere\xE7a ajuda para finalizar, use t\xE9cnica de urg\xEAncia (estoque limitado).` : "";
  const fullSystem = SYSTEM_PROMPT2 + nameCtx + cartNote;
  let response = await anthropic.messages.create({
    model: "claude-sonnet-4-6",
    max_tokens: 700,
    system: fullSystem,
    tools: LIA_TOOLS,
    messages
  });
  while (response.stop_reason === "tool_use") {
    const assistantContent = response.content;
    const toolUses = assistantContent.filter((b) => b.type === "tool_use");
    const toolResults = [];
    for (const toolUse of toolUses) {
      let result;
      try {
        const inp = toolUse.input;
        if (toolUse.name === "buscar_produtos") {
          console.log(`[WA Lia] buscando: "${inp.query}"`);
          result = await searchTrayProducts(inp.query);
        } else if (toolUse.name === "ver_produto") {
          console.log(`[WA Lia] acessando produto: ${inp.url}`);
          result = await fetchTrayPage(inp.url);
        } else {
          result = `Ferramenta desconhecida: ${toolUse.name}`;
        }
      } catch (e) {
        result = `Erro: ${e.message}`;
      }
      toolResults.push({ type: "tool_result", tool_use_id: toolUse.id, content: result });
    }
    messages.push({ role: "assistant", content: assistantContent });
    messages.push({ role: "user", content: toolResults });
    response = await anthropic.messages.create({
      model: "claude-sonnet-4-6",
      max_tokens: 700,
      system: fullSystem,
      tools: LIA_TOOLS,
      messages
    });
  }
  const reply = response.content.filter((b) => b.type === "text").map((b) => b.text).join("") || "Ol\xE1! Sou a Lia da Feminnita \u{1F60A} Como posso ajudar?";
  if (db) {
    await db.insert(conversationHistory).values({
      userId,
      whatsappPhoneNumber: phoneNumber,
      whatsappContactName: contactName || null,
      userMessage: incomingMessage,
      aiResponse: reply,
      confidence: "0.90",
      escalated: false,
      status: "open"
    }).catch(() => null);
  }
  return reply;
}

// server/routers/whatsapp-funnel-webhook.ts
var VERIFY_TOKEN = process.env.WHATSAPP_FUNNEL_VERIFY_TOKEN || "feminnita-funnel-2026";
async function sendWhatsAppReply(phoneNumberId, to, text3, token) {
  await fetch(`https://graph.facebook.com/v19.0/${phoneNumberId}/messages`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      messaging_product: "whatsapp",
      to,
      type: "text",
      text: { body: text3 }
    })
  });
}
async function markAsRead(phoneNumberId, messageId, token) {
  await fetch(`https://graph.facebook.com/v19.0/${phoneNumberId}/messages`, {
    method: "POST",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify({
      messaging_product: "whatsapp",
      status: "read",
      message_id: messageId
    })
  }).catch(() => null);
}
function registerWhatsAppFunnelWebhook(app) {
  app.get("/api/whatsapp/funnel", (req, res) => {
    const mode = req.query["hub.mode"];
    const token = req.query["hub.verify_token"];
    const challenge = req.query["hub.challenge"];
    if (mode === "subscribe" && token === VERIFY_TOKEN) {
      console.log("[WA Funnel] Webhook verificado pelo Meta");
      return res.status(200).send(challenge);
    }
    return res.status(403).send("Forbidden");
  });
  app.post("/api/whatsapp/funnel", async (req, res) => {
    res.status(200).send("OK");
    try {
      const body = req.body;
      if (body.object !== "whatsapp_business_account") return;
      const entry = body.entry?.[0];
      const changes = entry?.changes?.[0];
      const value = changes?.value;
      if (!value?.messages?.length) return;
      const message = value.messages[0];
      const phoneNumberId = value.metadata?.phone_number_id;
      const token = process.env.WHATSAPP_ACCESS_TOKEN || "";
      if (!token || !phoneNumberId) {
        console.warn("[WA Funnel] WHATSAPP_ACCESS_TOKEN ou phone_number_id ausente");
        return;
      }
      if (message.type !== "text") return;
      const from = message.from;
      const text3 = message.text?.body || "";
      const contactName = value.contacts?.[0]?.profile?.name || "";
      const messageId = message.id;
      console.log(`[WA Funnel] ${from} (${contactName}): ${text3.slice(0, 60)}`);
      markAsRead(phoneNumberId, messageId, token);
      const reply = await runWhatsAppFunnelAgent(from, contactName, text3);
      await sendWhatsAppReply(phoneNumberId, from, reply, token);
      console.log(`[WA Funnel] Resposta enviada para ${from}`);
    } catch (e) {
      console.error("[WA Funnel] Erro ao processar mensagem:", e.message);
    }
  });
}

