// server/integrations/bling.ts
var BLING_API_BASE_URL = "https://api.bling.com.br/Api/v3";
var BlingAPIError = class extends Error {
  constructor(statusCode, errors = [], message) {
    super(message || `Bling API Error: ${statusCode}`);
    this.statusCode = statusCode;
    this.errors = errors;
    this.name = "BlingAPIError";
  }
};
async function blingRequest(endpoint, accessToken, options = {}) {
  const url = `${BLING_API_BASE_URL}${endpoint}`;
  const headers = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${accessToken}`,
    ...options.headers
  };
  try {
    const response = await fetch(url, {
      ...options,
      headers
    });
    const data = await response.json();
    if (!response.ok) {
      const errorData = data;
      throw new BlingAPIError(
        response.status,
        errorData.erros || [],
        `Bling API Error: ${response.status}`
      );
    }
    return data;
  } catch (error) {
    if (error instanceof BlingAPIError) {
      throw error;
    }
    throw new BlingAPIError(500, [], `Bling API request failed: ${error}`);
  }
}
async function sincronizarProdutos(accessToken, pagina = 1, limite = 100) {
  return blingRequest(
    `/produtos?pagina=${pagina}&limite=${limite}`,
    accessToken
  );
}
async function sincronizarPedidos(accessToken, pagina = 1, limite = 100, dataInicio, dataFim) {
  let endpoint = `/pedidos?pagina=${pagina}&limite=${limite}`;
  if (dataInicio) {
    endpoint += `&dataInicio=${dataInicio}`;
  }
  if (dataFim) {
    endpoint += `&dataFim=${dataFim}`;
  }
  return blingRequest(endpoint, accessToken);
}
async function sincronizarContatos(accessToken, pagina = 1, limite = 100) {
  return blingRequest(
    `/contatos?pagina=${pagina}&limite=${limite}`,
    accessToken
  );
}
async function sincronizarEstoque(accessToken, pagina = 1, limite = 100) {
  return blingRequest(
    `/estoque?pagina=${pagina}&limite=${limite}`,
    accessToken
  );
}
function formatarErroBlng(error) {
  if (error.errors.length === 0) {
    return `Erro ${error.statusCode}: ${error.message}`;
  }
  return error.errors.map((e) => `${e.codigo}: ${e.mensagem}`).join("; ");
}

// server/routers/bling.ts
async function getBlingToken(userId) {
  const token = await getOAuthToken(userId, "bling");
  if (!token || !token.isActive) throw new Error("Bling n\xE3o conectado. Conecte sua conta Bling primeiro.");
  if (token.expiresAt && tokenExpirado(new Date(token.expiresAt))) {
    if (!token.refreshToken) throw new Error("Token Bling expirado. Reconecte sua conta.");
    const renewed = await renovarAccessToken(token.refreshToken);
    await saveOAuthToken(userId, "bling", {
      accessToken: renewed.access_token,
      refreshToken: token.refreshToken,
      expiresIn: renewed.expires_in
    });
    return renewed.access_token;
  }
  return token.accessToken;
}
