// server/routers/google-ads.ts
import { z as z6 } from "zod";

// server/integrations/google-ads-api.ts
var GOOGLE_ADS_API_URL = "https://googleads.googleapis.com/v15";
var GoogleAdsAPIError = class extends Error {
  constructor(statusCode, googleError, message) {
    super(message);
    this.statusCode = statusCode;
    this.googleError = googleError;
    this.name = "GoogleAdsAPIError";
  }
};
async function fazerRequisicaoGoogleAds(endpoint, accessToken, customerId, opcoes = {}) {
  const url = `${GOOGLE_ADS_API_URL}${endpoint}`;
  const headers = {
    "Content-Type": "application/json",
    Authorization: `Bearer ${accessToken}`,
    "developer-token": process.env.GOOGLE_ADS_DEVELOPER_TOKEN || "",
    "login-customer-id": customerId,
    ...opcoes.headers
  };
  try {
    const response = await fetch(url, {
      ...opcoes,
      headers
    });
    const data = await response.json();
    if (!response.ok) {
      throw new GoogleAdsAPIError(
        response.status,
        data.error,
        `Erro na Google Ads API: ${data.error?.message || response.statusText}`
      );
    }
    return data;
  } catch (error) {
    if (error instanceof GoogleAdsAPIError) {
      throw error;
    }
    throw new Error(`Erro ao conectar com Google Ads: ${error}`);
  }
}
async function obterCampanhasGoogleAds(accessToken, customerId) {
  const body = {
    query: `
      SELECT
        campaign.id,
        campaign.name,
        campaign.status,
        campaign.advertising_channel_type,
        campaign.start_date,
        campaign.end_date,
        metrics.impressions,
        metrics.clicks,
        metrics.cost_micros
      FROM campaign
      ORDER BY campaign.id
    `
  };
  return fazerRequisicaoGoogleAds(
    `/customers/${customerId}/googleAds:search`,
    accessToken,
    customerId,
    {
      method: "POST",
      body: JSON.stringify(body)
    }
  );
}
async function obterAnunciosGoogleAds(accessToken, customerId, campaignId) {
  const body = {
    query: `
      SELECT
        ad_group.id,
        ad_group.name,
        ad_group_ad.ad.id,
        ad_group_ad.ad.type,
        ad_group_ad.status,
        metrics.impressions,
        metrics.clicks,
        metrics.cost_micros,
        metrics.conversions
      FROM ad_group_ad
      WHERE campaign.id = ${campaignId}
      ORDER BY ad_group.id
    `
  };
  return fazerRequisicaoGoogleAds(
    `/customers/${customerId}/googleAds:search`,
    accessToken,
    customerId,
    {
      method: "POST",
      body: JSON.stringify(body)
    }
  );
}
async function obterPerformanceCampanha(accessToken, customerId, campaignId) {
  const body = {
    query: `
      SELECT
        campaign.id,
        campaign.name,
        metrics.impressions,
        metrics.clicks,
        metrics.cost_micros,
        metrics.conversions,
        metrics.conversion_value_micros,
        metrics.ctr,
        metrics.average_cpc_micros
      FROM campaign
      WHERE campaign.id = ${campaignId}
    `
  };
  return fazerRequisicaoGoogleAds(
    `/customers/${customerId}/googleAds:search`,
    accessToken,
    customerId,
    {
      method: "POST",
      body: JSON.stringify(body)
    }
  );
}
async function criarCampanhaGoogleAds(accessToken, customerId, dados) {
  const body = {
    customerId,
    operation: {
      create: {
        name: dados.name,
        advertisingChannelType: dados.advertisingChannelType,
        status: dados.status,
        campaignBudget: {
          amountMicros: dados.budget * 1e6,
          deliveryMethod: "STANDARD"
        }
      }
    }
  };
  return fazerRequisicaoGoogleAds(
    `/customers/${customerId}/campaigns`,
    accessToken,
    customerId,
    {
      method: "POST",
      body: JSON.stringify(body)
    }
  );
}
async function pausarCampanhaGoogleAds(accessToken, customerId, campaignId) {
  const body = {
    customerId,
    operation: {
      update: {
        resourceName: `customers/${customerId}/campaigns/${campaignId}`,
        status: "PAUSED"
      },
      updateMask: "status"
    }
  };
  return fazerRequisicaoGoogleAds(
    `/customers/${customerId}/campaigns/${campaignId}`,
    accessToken,
    customerId,
    {
      method: "PATCH",
      body: JSON.stringify(body)
    }
  );
}
function formatarErroGoogleAds(erro) {
  const mensagens = {
    400: "Requisi\xE7\xE3o inv\xE1lida",
    401: "N\xE3o autorizado - Token inv\xE1lido ou expirado",
    403: "Acesso proibido",
    404: "Recurso n\xE3o encontrado",
    429: "Muitas requisi\xE7\xF5es - Aguarde antes de tentar novamente",
    500: "Erro interno do servidor Google"
  };
  return mensagens[erro.statusCode] || `Erro ${erro.statusCode}: ${erro.message}`;
}

// server/routers/google-ads.ts
var googleAdsRouter = router({
  /**
   * Obtém campanhas do Google Ads
   */
  obterCampanhas: protectedProcedure.input(
    z6.object({
      accessToken: z6.string(),
      customerId: z6.string()
    })
  ).query(async ({ input }) => {
    try {
      const resultado = await obterCampanhasGoogleAds(
        input.accessToken,
        input.customerId
      );
      return {
        sucesso: true,
        campanhas: resultado.results || [],
        total: resultado.results?.length || 0
      };
    } catch (erro) {
      if (erro instanceof GoogleAdsAPIError) {
        throw new Error(formatarErroGoogleAds(erro));
      }
      throw erro;
    }
  }),
  /**
   * Obtém anúncios de uma campanha
   */
  obterAnuncios: protectedProcedure.input(
    z6.object({
      accessToken: z6.string(),
      customerId: z6.string(),
      campaignId: z6.string()
    })
  ).query(async ({ input }) => {
    try {
      const resultado = await obterAnunciosGoogleAds(
        input.accessToken,
        input.customerId,
        input.campaignId
      );
      return {
        sucesso: true,
        anuncios: resultado.results || [],
        total: resultado.results?.length || 0
      };
    } catch (erro) {
      if (erro instanceof GoogleAdsAPIError) {
        throw new Error(formatarErroGoogleAds(erro));
      }
      throw erro;
    }
  }),
  /**
   * Obtém performance de uma campanha
   */
  obterPerformance: protectedProcedure.input(
    z6.object({
      accessToken: z6.string(),
      customerId: z6.string(),
      campaignId: z6.string()
    })
  ).query(async ({ input }) => {
    try {
      const resultado = await obterPerformanceCampanha(
        input.accessToken,
        input.customerId,
        input.campaignId
      );
      return {
        sucesso: true,
        performance: resultado.results?.[0] || null
      };
    } catch (erro) {
      if (erro instanceof GoogleAdsAPIError) {
        throw new Error(formatarErroGoogleAds(erro));
      }
      throw erro;
    }
  }),
  /**
   * Cria uma nova campanha
   */
  criarCampanha: protectedProcedure.input(
    z6.object({
      accessToken: z6.string(),
      customerId: z6.string(),
      nome: z6.string(),
      tipoCanal: z6.string(),
      status: z6.string(),
      orcamento: z6.number()
    })
  ).mutation(async ({ input }) => {
    try {
      const resultado = await criarCampanhaGoogleAds(
        input.accessToken,
        input.customerId,
        {
          name: input.nome,
          advertisingChannelType: input.tipoCanal,
          status: input.status,
          budget: input.orcamento
        }
      );
      return {
        sucesso: true,
        resourceName: resultado.resourceName,
        mensagem: "Campanha criada com sucesso"
      };
    } catch (erro) {
      if (erro instanceof GoogleAdsAPIError) {
        throw new Error(formatarErroGoogleAds(erro));
      }
      throw erro;
    }
  }),
  /**
   * Pausa uma campanha
   */
  pausarCampanha: protectedProcedure.input(
    z6.object({
      accessToken: z6.string(),
      customerId: z6.string(),
      campaignId: z6.string()
    })
  ).mutation(async ({ input }) => {
    try {
      await pausarCampanhaGoogleAds(
        input.accessToken,
        input.customerId,
        input.campaignId
      );
      return {
        sucesso: true,
        mensagem: "Campanha pausada com sucesso"
      };
    } catch (erro) {
      if (erro instanceof GoogleAdsAPIError) {
        throw new Error(formatarErroGoogleAds(erro));
      }
      throw erro;
    }
  })
});

