      mainNumber: process.env.WHATSAPP_MAIN_NUMBER || "",
      businessName: process.env.WHATSAPP_BUSINESS_NAME || "Feminnita Pijamas",
      features: [
        "Confirma\xE7\xE3o de Pagamento",
        "Rastreio de Pedidos",
        "Aprova\xE7\xE3o de Postagens",
        "Lembrete de Tema",
        "Roteamento para Atendente",
        "Grupo VIP"
      ],
