function getNextPostingDay() {
  const today = /* @__PURE__ */ new Date();
  const dayOfWeek = today.getDay();
  let daysUntilPosting = 0;
  if (dayOfWeek === 2) {
    daysUntilPosting = 0;
  } else if (dayOfWeek === 5) {
    daysUntilPosting = 0;
  } else if (dayOfWeek < 2) {
    daysUntilPosting = 2 - dayOfWeek;
  } else if (dayOfWeek < 5) {
    daysUntilPosting = 5 - dayOfWeek;
  } else {
    daysUntilPosting = 3;
  }
  const nextPosting = new Date(today);
  nextPosting.setDate(nextPosting.getDate() + daysUntilPosting);
  nextPosting.setHours(14, 0, 0, 0);
  return nextPosting;
}
function getNextPostingDays(count2) {
  const days = [];
  let current = getNextPostingDay();
  for (let i = 0; i < count2; i++) {
    days.push(new Date(current));
    current.setDate(current.getDate() + 3);
  }
  return days;
}

