// server/services/webSearch.ts
var TAVILY_API_URL = "https://api.tavily.com/search";
var TAVILY_API_KEY = process.env.TAVILY_API_KEY || "";
async function searchWeb(query, options = {}) {
  if (!TAVILY_API_KEY) {
    console.warn("[WebSearch] TAVILY_API_KEY n\xE3o configurado \u2014 retornando resultado vazio");
    return { query, results: [] };
  }
  const {
    maxResults = 5,
    searchDepth = "basic",
    includeAnswer = true,
    topic = "news",
    days = 7
  } = options;
  try {
    const response = await fetch(TAVILY_API_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${TAVILY_API_KEY}`
      },
      body: JSON.stringify({
        query,
        max_results: maxResults,
        search_depth: searchDepth,
        include_answer: includeAnswer,
        topic,
        days
      })
    });
    if (!response.ok) {
      const errText = await response.text();
      console.error(`[WebSearch] Tavily error ${response.status}: ${errText}`);
      return { query, results: [] };
    }
    const data = await response.json();
    return {
      query,
      results: (data.results || []).map((r) => ({
        title: r.title || "",
        url: r.url || "",
        content: r.content || "",
        score: r.score || 0,
        publishedDate: r.published_date
      })),
      answer: data.answer
    };
  } catch (err) {
    console.error("[WebSearch] Falha ao chamar Tavily:", err.message);
    return { query, results: [] };
  }
}
function formatSearchResults(results) {
  if (results.results.length === 0 && !results.answer) {
    return `[Busca: "${results.query}" \u2014 sem resultados]`;
  }
  const lines = [];
  lines.push(`=== BUSCA WEB: "${results.query}" ===`);
  if (results.answer) {
    lines.push(`S\xEDntese: ${results.answer}`);
    lines.push("");
  }
  results.results.forEach((r, i) => {
    lines.push(`[${i + 1}] ${r.title}`);
    if (r.publishedDate) lines.push(`    Data: ${r.publishedDate}`);
    lines.push(`    ${r.content.slice(0, 300)}${r.content.length > 300 ? "..." : ""}`);
    lines.push("");
  });
  return lines.join("\n");
}
async function multiSearch(queries) {
  const results = await Promise.all(queries.map((q) => searchWeb(q)));
  return results.map(formatSearchResults).join("\n\n");
}

