// server/routers/instagram.ts
import { z as z29 } from "zod";

// server/instagram.ts
async function fetchInstagramPosts(instagramAccountId, accessToken, limit = 15) {
  try {
    const url = `https://graph.instagram.com/v18.0/${instagramAccountId}/media?fields=id,caption,media_type,media_url,permalink,timestamp,like_count,comments_count&limit=${limit}&access_token=${accessToken}`;
    const response = await fetch(url);
    if (!response.ok) {
      const error = await response.json();
      throw new Error(`Instagram API Error: ${JSON.stringify(error)}`);
    }
    const data = await response.json();
    return data.data || [];
  } catch (error) {
    console.error("Failed to fetch Instagram posts:", error);
    throw error;
  }
}
async function publishInstagramPost(instagramAccountId, accessToken, caption, imageUrl, scheduledPublishTime) {
  try {
    const containerUrl = `https://graph.instagram.com/v18.0/${instagramAccountId}/media`;
    const containerPayload = {
      image_url: imageUrl,
      caption,
      access_token: accessToken,
      ...scheduledPublishTime && { scheduled_publish_time: scheduledPublishTime }
    };
    const containerResponse = await fetch(containerUrl, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(containerPayload)
    });
    if (!containerResponse.ok) {
      const error = await containerResponse.json();
      throw new Error(`Failed to create media container: ${JSON.stringify(error)}`);
    }
    const containerData = await containerResponse.json();
    if (!scheduledPublishTime) {
      const publishUrl = `https://graph.instagram.com/v18.0/${instagramAccountId}/media_publish`;
      const publishPayload = {
        creation_id: containerData.id,
        access_token: accessToken
      };
      const publishResponse = await fetch(publishUrl, {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify(publishPayload)
      });
      if (!publishResponse.ok) {
        const error = await publishResponse.json();
        throw new Error(`Failed to publish post: ${JSON.stringify(error)}`);
      }
      return await publishResponse.json();
    }
    return containerData;
  } catch (error) {
    console.error("Failed to publish Instagram post:", error);
    throw error;
  }
}
async function publishFacebookPost(pageId, accessToken, caption, imageUrl, scheduledPublishTime) {
  try {
    const url = `https://graph.facebook.com/v18.0/${pageId}/feed`;
    const payload = {
      message: caption,
      link: imageUrl,
      access_token: accessToken
    };
    if (scheduledPublishTime) {
      payload.scheduled_publish_time = Math.floor(new Date(scheduledPublishTime).getTime() / 1e3);
    }
    const response = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify(payload)
    });
    if (!response.ok) {
      const error = await response.json();
      throw new Error(`Facebook API Error: ${JSON.stringify(error)}`);
    }
    return await response.json();
  } catch (error) {
    console.error("Failed to publish Facebook post:", error);
    throw error;
  }
}

// server/routers/instagram.ts
var instagramRouter = router({
  /**
   * Busca os últimos posts do Instagram da Feminnita
   */
  fetchPosts: protectedProcedure.input(z29.object({
    limit: z29.number().default(15)
  })).query(async ({ input }) => {
    try {
      const instagramAccountId = process.env.INSTAGRAM_ACCOUNT_ID || "";
      const accessToken = process.env.META_ACCESS_TOKEN || "";
      if (!instagramAccountId || !accessToken) {
        throw new Error("Instagram credentials not configured");
      }
      const realInstagramAccountId = process.env.INSTAGRAM_ACCOUNT_ID || instagramAccountId;
      const posts = await fetchInstagramPosts(
        realInstagramAccountId,
        accessToken,
        input.limit
      );
      return {
        success: true,
        posts,
        count: posts.length
      };
    } catch (error) {
      console.error("Failed to fetch Instagram posts:", error);
      return {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error",
        posts: []
      };
    }
  }),
  /**
   * Publica um post no Instagram (agendado ou imediato)
   */
  publishPost: protectedProcedure.input(z29.object({
    caption: z29.string(),
    imageUrl: z29.string().url(),
    scheduledPublishTime: z29.string().optional(),
    platforms: z29.array(z29.enum(["instagram", "facebook"])).default(["instagram"])
  })).mutation(async ({ input, ctx }) => {
    try {
      const instagramAccountId = "59536615191";
      const pageId = process.env.META_PAGE_ID || "";
      const accessToken = process.env.META_ACCESS_TOKEN || "";
      if (!accessToken) {
        throw new Error("Meta access token not configured");
      }
      const results = {};
      if (input.platforms.includes("instagram")) {
        try {
          results.instagram = await publishInstagramPost(
            instagramAccountId,
            accessToken,
            input.caption,
            input.imageUrl,
            input.scheduledPublishTime
          );
        } catch (error) {
          results.instagram = {
            error: error instanceof Error ? error.message : "Unknown error"
          };
        }
      }
      if (input.platforms.includes("facebook") && pageId) {
        try {
          results.facebook = await publishFacebookPost(
            pageId,
            accessToken,
            input.caption,
            input.imageUrl,
            input.scheduledPublishTime
          );
        } catch (error) {
          results.facebook = {
            error: error instanceof Error ? error.message : "Unknown error"
          };
        }
      }
      return {
        success: true,
        results
      };
    } catch (error) {
      console.error("Failed to publish post:", error);
      return {
        success: false,
        error: error instanceof Error ? error.message : "Unknown error"
      };
    }
  })
});

