async function generatePostForInfluencer(influencer) {
  const result = await invokeLLM({
    messages: [
      {
        role: "system",
        content: "Voc\xEA \xE9 um especialista em marketing digital para moda e lifestyle. Gere posts para Instagram de influenciadoras virtuais da marca Feminnita Pijamas."
      },
      {
        role: "user",
        content: `Crie um post para Instagram para a influenciadora ${influencer.name}.
Personalidade: ${influencer.personality || "jovem, descontra\xEDda e feminina"}
Bio: ${influencer.bio || "Influenciadora digital apaixonada por moda e conforto"}
Marca: Feminnita Pijamas (atacado)

Retorne um JSON com os campos:
- caption: legenda do post (m\xE1ximo 150 caracteres, envolvente e aut\xEAntica)
- hashtags: array com 5-8 hashtags relevantes sem o s\xEDmbolo #`
      }
    ],
    outputSchema: {
      name: "post_content",
      schema: {
        type: "object",
        properties: {
          caption: { type: "string" },
          hashtags: { type: "array", items: { type: "string" } }
        },
        required: ["caption", "hashtags"],
        additionalProperties: false
      },
      strict: true
    }
  });
  const text3 = typeof result.choices[0].message.content === "string" ? result.choices[0].message.content : "";
  const parsed = JSON.parse(text3);
  return {
    caption: parsed.caption || `Post de ${influencer.name} - Feminnita Pijamas`,
    hashtags: Array.isArray(parsed.hashtags) ? parsed.hashtags : ["feminnita", "pijamas", "conforto"]
  };
}
