async function searchKnowledgeBase(db, userId, query, limit) {
  const keywords = query.toLowerCase().split(" ");
  let results = await db.select().from(knowledgeBase).where(
    and34(
      eq37(knowledgeBase.userId, userId),
      eq37(knowledgeBase.isActive, true)
    )
  );
  results = results.filter((item) => {
    const text3 = `${item.title} ${item.description || ""}`.toLowerCase();
    return keywords.some((keyword) => text3.includes(keyword));
  });
  return results.slice(0, limit);
}
function buildSystemPrompt(customPrompt, trainingExamples, relevantProducts) {
  let prompt = customPrompt || `Voc\xEA \xE9 um assistente de atendimento ao cliente amig\xE1vel e profissional para a Feminnita Pijamas.
Sua responsabilidade \xE9 ajudar os clientes com d\xFAvidas sobre produtos, pedidos e pol\xEDticas.
Sempre seja educado, conciso e \xFAtil.
Se n\xE3o souber a resposta, ofere\xE7a conectar com um atendente humano.`;
  if (trainingExamples.length > 0) {
    prompt += "\n\nExemplos de conversas anteriores:\n";
    trainingExamples.slice(0, 3).forEach((example) => {
      prompt += `
Cliente: ${example.userMessage}
Voc\xEA: ${example.expectedResponse}`;
    });
  }
  if (relevantProducts.length > 0) {
    prompt += "\n\nProdutos relevantes para esta conversa:\n";
    relevantProducts.forEach((product) => {
      prompt += `
- ${product.title}: ${product.description || ""}`;
      if (product.url) {
        prompt += ` (${product.url})`;
      }
    });
  }
  return prompt;
}
function checkEscalationKeywords(message, keywords) {
  const defaultKeywords = [
    "atendente",
    "humano",
    "falar com",
    "suporte",
    "gerente",
    "reclama\xE7\xE3o",
    "problema",
    "urgente"
  ];
  const allKeywords = [...defaultKeywords, ...keywords];
  const lowerMessage = message.toLowerCase();
  return allKeywords.some((keyword) => lowerMessage.includes(keyword));
}
async function createEscalation(db, userId, whatsappPhoneNumber, whatsappContactName, reason) {
  const lastConversation = await db.select().from(conversationHistory).where(
    and34(
      eq37(conversationHistory.userId, userId),
      eq37(conversationHistory.whatsappPhoneNumber, whatsappPhoneNumber)
    )
  ).orderBy(desc18(conversationHistory.createdAt)).limit(1);
  if (lastConversation.length > 0) {
    await db.insert(escalationQueue).values({
      userId,
      conversationHistoryId: lastConversation[0].id,
      whatsappPhoneNumber,
      whatsappContactName,
      reason,
      priority: "medium",
      status: "waiting"
    });
    await notifyOwner({
      title: "Nova Escala\xE7\xE3o de Atendimento",
      content: `Cliente ${whatsappContactName || whatsappPhoneNumber} foi escalado para atendimento humano. Motivo: ${reason}`
    });
  }
}

