async function sendWhatsAppMessage2(userId, phoneNumber, messageText, mediaUrl) {
  try {
    const phoneNumberId = await getWhatsAppPhoneNumberId(userId);
    if (!phoneNumberId) {
      console.error("WhatsApp Phone Number ID n\xE3o configurado");
      return null;
    }
    const body = {
      messaging_product: "whatsapp",
      to: phoneNumber,
      type: mediaUrl ? "image" : "text"
    };
    if (mediaUrl) {
      body.image = {
        link: mediaUrl
      };
    } else {
      body.text = {
        preview_url: true,
        body: messageText
      };
    }
    const response = await fetch(
      `https://graph.instagram.com/v18.0/${phoneNumberId}/messages`,
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${process.env.META_ACCESS_TOKEN}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify(body)
      }
    );
    const data = await response.json();
    if (!response.ok) {
      console.error("WhatsApp API error:", data.error);
      return null;
    }
    return {
      messageId: data.messages?.[0]?.id || ""
    };
  } catch (error) {
    console.error("[WhatsApp Send] Erro:", error);
    return null;
  }
}
async function getWhatsAppPhoneNumberId(userId) {
  return process.env.META_WHATSAPP_PHONE_NUMBER_ID || null;
}

