function graphUrl(path16, token, extraFields) {
  const base = `https://graph.facebook.com/v19.0${path16}`;
  const params = new URLSearchParams({ access_token: token });
  if (extraFields) params.set("fields", extraFields);
  return `${base}?${params.toString()}`;
}
async function exchangeForLongLivedToken(shortToken) {
  const appId = process.env.META_APP_ID;
  const appSecret = process.env.META_APP_SECRET;
  if (!appId || !appSecret) {
    console.warn("[Instagram] META_APP_ID/META_APP_SECRET n\xE3o configurados \u2014 token n\xE3o ser\xE1 renovado");
    return shortToken;
  }
  try {
    const url = new URL("https://graph.facebook.com/oauth/access_token");
    url.searchParams.set("grant_type", "fb_exchange_token");
    url.searchParams.set("client_id", appId);
    url.searchParams.set("client_secret", appSecret);
    url.searchParams.set("fb_exchange_token", shortToken);
    const res = await fetch(url.toString());
    const data = await res.json();
    if (data.error) {
      console.warn("[Instagram] Troca de token falhou:", data.error.message, "\u2014 usando token original");
      return shortToken;
    }
    console.log("[Instagram] Token trocado por long-lived com sucesso. Expira em:", Math.round((data.expires_in ?? 0) / 86400), "dias");
    return data.access_token ?? shortToken;
  } catch (err) {
    console.warn("[Instagram] Erro na troca de token:", err.message);
    return shortToken;
  }
}
