import { eq as eq56, and as and51 } from "drizzle-orm";
var BASE_URL3 = "https://graph.facebook.com/v19.0";
var ENV_TOKEN = process.env.META_ACCESS_TOKEN || "";
var ENV_ACCOUNT = process.env.META_AD_ACCOUNT_ID || "";
async function getValidMetaCredentials(userId) {
  const db = await getDb();
  if (!db) return null;
  const rows = await db.select({
    accessToken: oauthTokens.accessToken,
    accountInfo: oauthTokens.accountInfo
  }).from(oauthTokens).where(and51(
    eq56(oauthTokens.userId, userId),
    eq56(oauthTokens.plataforma, "meta"),
    eq56(oauthTokens.isActive, true)
  )).limit(1);
  if (rows.length === 0) return null;
  const info = rows[0].accountInfo ? JSON.parse(rows[0].accountInfo) : {};
  const accountId = info.adAccountId ?? "";
  return { token: rows[0].accessToken, accountId };
}
async function setMetaAdAccountId(userId, adAccountId) {
  const db = await getDb();
  if (!db) return;
  const rows = await db.select({ id: oauthTokens.id, accountInfo: oauthTokens.accountInfo }).from(oauthTokens).where(and51(eq56(oauthTokens.userId, userId), eq56(oauthTokens.plataforma, "meta"))).limit(1);
  if (rows.length === 0) return;
  const info = rows[0].accountInfo ? JSON.parse(rows[0].accountInfo) : {};
  info.adAccountId = adAccountId;
  await db.update(oauthTokens).set({ accountInfo: JSON.stringify(info) }).where(eq56(oauthTokens.id, rows[0].id));
}
async function getMetaConnectionStatus(userId) {
  const creds = await getValidMetaCredentials(userId);
  if (creds) return { connected: true, adAccountId: creds.accountId || null, source: "db" };
  if (ENV_TOKEN) return { connected: true, adAccountId: ENV_ACCOUNT || null, source: "env" };
  return { connected: false, adAccountId: null, source: "none" };
}
async function metaGet(path16, params = {}, creds) {
  const token = creds?.token ?? ENV_TOKEN;
  const query = new URLSearchParams({ access_token: token, ...params });
  const res = await fetch(`${BASE_URL3}${path16}?${query}`);
  const json3 = await res.json();
  if (json3.error) throw new Error(`Meta API: ${json3.error.message}`);
  return json3;
}
async function metaPost(path16, body = {}, creds) {
  const token = creds?.token ?? ENV_TOKEN;
  const res = await fetch(`${BASE_URL3}${path16}`, {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({ access_token: token, ...body })
  });
  const json3 = await res.json();
  if (json3.error) throw new Error(`Meta API: ${json3.error.message}`);
  return json3;
}
async function fetchCampaigns(datePreset, creds) {
  const account = creds?.accountId ?? ENV_ACCOUNT;
  const fields = [
    "campaign_id",
    "campaign_name",
    "spend",
    "impressions",
    "clicks",
    "ctr",
    "cpm",
    "cpp",
    "reach",
    "frequency",
    "actions"
  ].join(",");
  const data = await metaGet(`/${account}/insights`, {
    level: "campaign",
    date_preset: datePreset,
    fields,
    limit: "20"
  }, creds);
  return (data.data || []).map((row) => {
    const purchaseAction = (row.actions || []).find(
      (a) => a.action_type === "purchase" || a.action_type === "omni_purchase"
    );
    const revenue = purchaseAction ? parseFloat(purchaseAction.value) : 0;
    const spend = parseFloat(row.spend || "0");
    return {
      id: row.campaign_id,
      name: row.campaign_name,
      status: "ACTIVE",
      spend,
      impressions: parseInt(row.impressions || "0"),
      clicks: parseInt(row.clicks || "0"),
      ctr: parseFloat(row.ctr || "0"),
      cpm: parseFloat(row.cpm || "0"),
      cpp: parseFloat(row.cpp || "0"),
      reach: parseInt(row.reach || "0"),
      frequency: parseFloat(row.frequency || "0"),
      actions: row.actions || [],
      roas: spend > 0 && revenue > 0 ? revenue / spend : void 0
    };
  });
}
async function fetchMetaAdsData(creds) {
  const token = creds?.token ?? ENV_TOKEN;
  if (!token || token === "seu_token_de_acesso_meta") {
    return { spendToday: 0, spendMonth: 0, campaigns: [], error: "Token Meta n\xE3o configurado" };
  }
  try {
    const [todayCampaigns, monthCampaigns] = await Promise.all([
      fetchCampaigns("today", creds),
      fetchCampaigns("this_month", creds)
    ]);
    const spendToday = todayCampaigns.reduce((sum, c) => sum + c.spend, 0);
    const spendMonth = monthCampaigns.reduce((sum, c) => sum + c.spend, 0);
    return { spendToday, spendMonth, campaigns: monthCampaigns };
  } catch (err) {
    console.error("[MetaAdsService] Erro:", err.message);
    return { spendToday: 0, spendMonth: 0, campaigns: [], error: err.message };
  }
}
async function fetchMetaCampaignsList(creds) {
  const account = creds?.accountId ?? ENV_ACCOUNT;
  const data = await metaGet(`/${account}/campaigns`, {
    fields: "id,name,status,effective_status,objective",
    limit: "30"
  }, creds);
  return (data.data || []).map((c) => ({
    id: c.id,
    name: c.name,
    status: c.status,
    effectiveStatus: c.effective_status || c.status,
    objective: c.objective
  }));
}
async function fetchMetaAdsets(campaignId, creds) {
  const account = creds?.accountId ?? ENV_ACCOUNT;
  const path16 = campaignId ? `/${campaignId}/adsets` : `/${account}/adsets`;
  const fields = "id,name,campaign_id,campaign{name},status,daily_budget,lifetime_budget";
  const data = await metaGet(path16, { fields, limit: "30" }, creds);
  const insightsData = await metaGet(`/${account}/insights`, {
    level: "adset",
    date_preset: "this_month",
    fields: "adset_id,spend,impressions,clicks,ctr,cpm,actions",
    limit: "30",
    ...campaignId ? { filtering: JSON.stringify([{ field: "campaign.id", operator: "EQUAL", value: campaignId }]) } : {}
  }, creds);
  const insightsMap = {};
  for (const row of insightsData.data || []) {
    insightsMap[row.adset_id] = row;
  }
  return (data.data || []).map((adset) => {
    const ins = insightsMap[adset.id] || {};
    const spend = parseFloat(ins.spend || "0");
    const purchaseAction = (ins.actions || []).find(
      (a) => a.action_type === "purchase" || a.action_type === "omni_purchase"
    );
    const revenue = purchaseAction ? parseFloat(purchaseAction.value) : 0;
    return {
      id: adset.id,
      name: adset.name,
      campaignId: adset.campaign_id,
      campaignName: adset.campaign?.name || "",
      status: adset.status,
      dailyBudget: adset.daily_budget ? parseInt(adset.daily_budget) / 100 : void 0,
      lifetimeBudget: adset.lifetime_budget ? parseInt(adset.lifetime_budget) / 100 : void 0,
      spend,
      impressions: parseInt(ins.impressions || "0"),
      clicks: parseInt(ins.clicks || "0"),
      ctr: parseFloat(ins.ctr || "0"),
      cpm: parseFloat(ins.cpm || "0"),
      roas: spend > 0 && revenue > 0 ? revenue / spend : void 0
    };
  });
}
async function fetchMetaInsights(level, datePreset, objectId, creds) {
  const account = creds?.accountId ?? ENV_ACCOUNT;
  const path16 = objectId ? `/${objectId}/insights` : `/${account}/insights`;
  const fields = [
    "campaign_name",
    "adset_name",
    "ad_name",
    "spend",
    "impressions",
    "clicks",
    "ctr",
    "cpm",
    "cpc",
    "cpp",
    "reach",
    "frequency",
    "actions",
    "cost_per_action_type"
  ].join(",");
  const data = await metaGet(path16, { level, date_preset: datePreset, fields, limit: "30" }, creds);
  return data.data || [];
}
async function fetchMetaAds(adsetId, campaignId, creds) {
  const account = creds?.accountId ?? ENV_ACCOUNT;
  const path16 = adsetId ? `/${adsetId}/ads` : campaignId ? `/${campaignId}/ads` : `/${account}/ads`;
  const fields = "id,name,status,adset_id,adset{name,campaign{name}},creative{id,thumbnail_url,image_url,body,title,call_to_action_type,link_url,object_story_spec}";
  let ads = [];
  try {
    const data = await metaGet(path16, { fields, limit: "30" }, creds);
    ads = data.data || [];
  } catch (err) {
    console.warn("[MetaAds] Erro ao buscar ads:", err.message);
    return [];
  }
  const insPath = adsetId ? `/${adsetId}/insights` : campaignId ? `/${campaignId}/insights` : `/${account}/insights`;
  let insMap = {};
  try {
    const insData = await metaGet(insPath, {
      level: "ad",
      date_preset: "last_30d",
      fields: "ad_id,spend,impressions,clicks,ctr,actions",
      limit: "30"
    }, creds);
    for (const row of insData.data || []) insMap[row.ad_id] = row;
  } catch {
  }
  return ads.map((ad) => {
    const creative = ad.creative || {};
    const ins = insMap[ad.id] || {};
    const spend = parseFloat(ins.spend || "0");
    const purchaseAction = (ins.actions || []).find(
      (a) => a.action_type === "purchase" || a.action_type === "omni_purchase"
    );
    const revenue = purchaseAction ? parseFloat(purchaseAction.value) * 400 : 0;
    const linkUrl = creative.link_url || creative.object_story_spec?.link_data?.link || creative.object_story_spec?.video_data?.call_to_action?.value?.link || void 0;
    return {
      id: ad.id,
      name: ad.name,
      status: ad.status,
      adsetId: ad.adset_id,
      adsetName: ad.adset?.name || "",
      campaignName: ad.adset?.campaign?.name || "",
      thumbnailUrl: creative.thumbnail_url || void 0,
      imageUrl: creative.image_url || void 0,
      body: creative.body || void 0,
      title: creative.title || void 0,
      callToActionType: creative.call_to_action_type || void 0,
      linkUrl,
      spend,
      impressions: parseInt(ins.impressions || "0"),
      clicks: parseInt(ins.clicks || "0"),
      ctr: parseFloat(ins.ctr || "0"),
      roas: spend > 0 && revenue > 0 ? revenue / spend : void 0
    };
  });
}
async function pauseCampaign(campaignId, creds) {
  await metaPost(`/${campaignId}`, { status: "PAUSED" }, creds);
  return { success: true };
}
async function resumeCampaign(campaignId, creds) {
  await metaPost(`/${campaignId}`, { status: "ACTIVE" }, creds);
  return { success: true };
}
