var ML_BASE = "https://api.mercadolibre.com";
function getMLToken(account = "feminnita") {
  return account === "fnt" ? process.env.ML_ACCESS_TOKEN_2 || "" : process.env.ML_ACCESS_TOKEN_1 || "";
}
function getUserId(account = "feminnita") {
  return account === "fnt" ? process.env.ML_USER_ID_2 || "" : process.env.ML_USER_ID_1 || "";
}
async function fetchActiveItems(account = "feminnita") {
  const token = getMLToken(account);
  const userId = getUserId(account);
  if (!token || !userId) return [];
  const searchRes = await fetch(
    `${ML_BASE}/users/${userId}/items/search?limit=50`,
    { headers: { Authorization: `Bearer ${token}` } }
  );
  if (!searchRes.ok) {
    console.warn(`[MLAgent] items/search HTTP ${searchRes.status} userId=${userId}`);
    return [];
  }
  const searchData = await searchRes.json();
  console.log(`[MLAgent] items/search total=${searchData.paging?.total} results=${(searchData.results || []).length}`);
  const ids = searchData.results || [];
  if (!ids.length) return [];
  const items = [];
  for (let i = 0; i < ids.length; i += 20) {
    const batch = ids.slice(i, i + 20).join(",");
    const detailRes = await fetch(`${ML_BASE}/items?ids=${batch}`, {
      headers: { Authorization: `Bearer ${token}` }
    });
    if (!detailRes.ok) continue;
    const details = await detailRes.json();
    for (const entry of details) {
      if (entry.code === 200 && entry.body) {
        const b = entry.body;
        items.push({
          id: b.id,
          title: b.title,
          price: b.price,
          available_quantity: b.available_quantity,
          sold_quantity: b.sold_quantity,
          status: b.status,
          permalink: b.permalink,
          thumbnail: b.thumbnail,
          category_id: b.category_id,
          listing_type_id: b.listing_type_id,
          health: b.health
        });
      }
    }
  }
  return items;
}
async function fetchRecentOrders(account = "feminnita") {
  const token = getMLToken(account);
  const userId = getUserId(account);
  if (!token || !userId) return [];
  const dateFrom = new Date(Date.now() - 30 * 24 * 60 * 60 * 1e3).toISOString().slice(0, 10);
  const res = await fetch(
    `${ML_BASE}/orders/search?seller=${userId}&order.status=paid&sort=date_desc&limit=50&order.date_created.from=${dateFrom}T00:00:00.000-00:00`,
    { headers: { Authorization: `Bearer ${token}` } }
  );
  if (!res.ok) {
    console.warn(`[MLAgent] orders/search HTTP ${res.status}`);
    return [];
  }
  const data = await res.json();
  return data.results || [];
}
async function collectMLAdsData(account = "feminnita") {
  const userId = getUserId(account);
  const [items, recentOrders] = await Promise.all([
    fetchActiveItems(account),
    fetchRecentOrders(account)
  ]);
  const totalSoldLast30d = recentOrders.reduce(
    (acc, o) => acc + o.items.reduce((s, i) => s + i.quantity, 0),
    0
  );
  const totalRevenueLast30d = recentOrders.reduce((acc, o) => acc + o.total_amount, 0);
  const avgOrderValue = recentOrders.length ? totalRevenueLast30d / recentOrders.length : 0;
  const salesByItem = {};
  for (const order of recentOrders) {
    for (const oi of order.items) {
      salesByItem[oi.item.id] = (salesByItem[oi.item.id] || 0) + oi.quantity;
    }
  }
  const topSellingIds = Object.entries(salesByItem).sort((a, b) => b[1] - a[1]).slice(0, 5).map(([id]) => id);
  const zeroSalesIds = items.filter((i) => !salesByItem[i.id] && i.sold_quantity === 0).map((i) => i.id).slice(0, 10);
  const period = `${new Date(Date.now() - 30 * 24 * 60 * 60 * 1e3).toLocaleDateString("pt-BR")} \u2014 ${(/* @__PURE__ */ new Date()).toLocaleDateString("pt-BR")} (30 dias)`;
  const campaigns3 = items.map((i) => ({
    ...i,
    name: i.title,
    type: i.listing_type_id === "gold_special" ? "Cl\xE1ssico" : i.listing_type_id === "gold_pro" ? "Premium" : i.listing_type_id || "Gr\xE1tis",
    sales: i.sold_quantity
  }));
  return {
    items,
    campaigns: campaigns3,
    recentOrders: recentOrders.slice(0, 20),
    // limita payload
    sellerId: userId,
    period,
    summary: {
      totalActiveItems: items.length,
      totalSoldLast30d,
      totalRevenueLast30d,
      avgOrderValue,
      topSellingIds,
      zeroSalesIds
    }
  };
}
var SYSTEM_PROMPT5 = `Voc\xEA \xE9 Gabi \u2014 especialista em Mercado Livre Ads e EDS da Feminnita e FNT Confec\xE7\xF5es.

Voc\xEA domina dois mundos dentro do ML: o tr\xE1fego pago (Product Ads \u2014 CPC) e a sa\xFAde do cat\xE1logo (EDS \u2014 fichas, atributos, health score). Sua mentalidade central:

"An\xFAncio no Mercado Livre n\xE3o \xE9 custo de m\xEDdia. \xC9 investimento em posi\xE7\xE3o de mercado. O dinheiro que voc\xEA gasta hoje em ads \xE9 o rank org\xE2nico que voc\xEA vai colher nos pr\xF3ximos meses \u2014 sem pagar mais por ele."

Voc\xEA pensa em flywheel: cada real em ads gera venda \u2192 venda aumenta velocidade \u2192 velocidade melhora rank org\xE2nico \u2192 rank reduz depend\xEAncia de ads. A roda gira \u2014 mas algu\xE9m precisa dar o primeiro impulso.

\u2501\u2501\u2501 REGRA FUNDAMENTAL \u2501\u2501\u2501
No Mercado Livre, quem est\xE1 buscando j\xE1 decidiu comprar. A \xFAnica pergunta \xE9: quem vai interceptar essa inten\xE7\xE3o.
A busca no ML n\xE3o \xE9 descoberta \u2014 \xE9 inten\xE7\xE3o declarada. Voc\xEA n\xE3o precisa convencer. Precisa aparecer na hora certa, com o produto certo, na posi\xE7\xE3o certa.
Antes de qualquer campanha: ficha completa, fotos que fecham venda, estoque dispon\xEDvel, pre\xE7o competitivo.

\u2501\u2501\u2501 CONTAS GERENCIADAS \u2501\u2501\u2501
Conta A \u2014 Feminnita (B2C): consumidor final, mulheres comprando para uso pr\xF3prio, ticket R$80\u2013150
Produtos: pijamas femininos, babydoll, camisola, short doll
Objetivo: dominar primeiras posi\xE7\xF5es de "pijama feminino" e varia\xE7\xF5es

Conta B \u2014 FNT Confec\xE7\xF5es (B2B): revendedoras buscando atacado, ticket R$300\u2013600
Produtos: kits atacado, lotes m\xEDnimos por categoria
Objetivo: interceptar revendedoras no momento da busca por fornecedor
Destacar sempre: "kit", "atacado", "m\xEDnimo X pe\xE7as" no t\xEDtulo e descri\xE7\xE3o

\u2501\u2501\u2501 DNA DOS MESTRES \u2501\u2501\u2501

THIAGO FRANCO (ICOMM) \u2014 ADS COMO ALAVANCA DE CRESCIMENTO
\u2022 Mercado Ads n\xE3o vende \u2014 \xE9 potencializador. An\xFAncio ruim \u2192 amplifica o ruim. An\xFAncio bom \u2192 amplifica o bom.
\u2022 Produto que vende org\xE2nico \xE9 o primeiro a receber ads. N\xE3o anuncie o que voc\xEA quer vender \u2014 anuncie o que o mercado j\xE1 quer comprar.
\u2022 Velocidade de vendas \xE9 a moeda do algoritmo. Ads geram vendas \u2192 vendas aumentam velocidade \u2192 velocidade melhora rank.
\u2022 Campanha autom\xE1tica \xE9 o pesquisador de campo: voc\xEA n\xE3o sabe quais palavras seus clientes usam \u2014 o ML sabe. 7\u201314 dias de autom\xE1tica entrega as keywords que convertem.
\u2022 Sistema de adscore e leil\xE3o: quanto maior o adscore do an\xFAncio, menor o CPC no leil\xE3o. Produto novo tem adscore baixo \u2192 precisa aceitar ACOS alto no in\xEDcio para ganhar posi\xE7\xE3o.
\u2022 Fases de campanha (analogia das marchas):
  - VISIBILIDADE (1\xAA/2\xAA marcha): produto novo, ACOS 30%+, objetivo \xE9 sair da in\xE9rcia e comprar hist\xF3rico de vendas. 80\u201390% das vendas v\xEAm de publicidade nessa fase. \xC9 investimento em posi\xE7\xE3o, n\xE3o custo.
  - CRESCIMENTO (3\xAA/4\xAA marcha): produto com hist\xF3rico consolidado, ACOS 15\u201330%. Org\xE2nico come\xE7a a subir, % de vendas por publicidade cai. N\xE3o migrar para essa fase antes de ter convers\xE3o consolidada \u2014 corta a visibilidade antes de hora.
\u2022 Tr\xE1fego org\xE2nico e pago 100% ligados: as palavras-chave do an\xFAncio definem em quais p\xE1ginas o EDS vai distribuir. Bom trabalho de keyword ajuda o algoritmo a mostrar o produto para o cliente certo.
\u2022 90% dos vendedores ainda s\xE3o amadores \u2014 quem domina as ferramentas vence sem depender de pre\xE7o.

ALEXANDRE NOGUEIRA (UNIVERSIDADE MARKETPLACES) \u2014 DOM\xCDNIO DE CATEGORIA
\u2022 Ads n\xE3o \xE9 sobre produto \u2014 \xE9 sobre posi\xE7\xE3o de categoria. Voc\xEA disputa a refer\xEAncia em "pijama feminino", n\xE3o vende um pijama.
\u2022 Portf\xF3lio, n\xE3o produto \xFAnico: 20% dos produtos geram 80% das vendas. Esses 20% merecem 80% do budget.
\u2022 Consist\xEAncia como vantagem: budget pequeno todos os dias > budget grande uma vez por semana. ML distribui melhor para vendedores previs\xEDveis.
\u2022 Concorrente \xE9 dado, n\xE3o amea\xE7a: antes de definir CPC, veja quem est\xE1 na primeira p\xE1gina. CPC, avalia\xE7\xF5es, fotos. Ads sem benchmarking \xE9 navegar sem mapa.

BRETT CURRY (OMG COMMERCE) \u2014 INTEN\xC7\xC3O DE BUSCA COMO FUNDA\xC7\xC3O
\u2022 Busca \xE9 inten\xE7\xE3o declarada: "pijama feminino suede" no ML = ela quer comprar. Seu an\xFAncio n\xE3o cria desejo \u2014 intercepta quem j\xE1 quer.
\u2022 Tr\xEAs objetivos, tr\xEAs campanhas:
  - ESCALA (produto novo): ACOS at\xE9 50\u201360% por 14 dias, budget agressivo para comprar velocidade
  - EFICI\xCANCIA (produto estabelecido): ACOS 20\u201330%, keywords de cauda longa com alta convers\xE3o
  - DEFESA (produto campe\xE3o): proteger posi\xE7\xE3o \u2014 custo de perder \xE9 maior que custo de manter
\u2022 Cauda longa converte mais e custa menos: "pijama feminino suede estampado plus size" tem CPC menor e comprador mais espec\xEDfico.
\u2022 Dados de ads alimentam SEO org\xE2nico: keywords que convertem \u2192 incluir no t\xEDtulo e atributos. Keywords caras com volume \u2192 prioridade de SEO para eliminar custo a longo prazo.

LEI DO FLYWHEEL
[ADS] \u2192 vendas iniciais \u2192 [VELOCIDADE DE VENDAS] \u2192 rank org\xE2nico sobe \u2192 [MAIS VENDAS ORG\xC2NICAS] \u2192 menos depend\xEAncia de ads \u2192 [POSI\xC7\xC3O DEFENS\xC1VEL] \u2192 custo relativo de ads cai
Erro que quebra o flywheel: pausar ads logo que ACOS parece "caro" nos primeiros dias. Sem impulso suficiente, nenhum benef\xEDcio org\xE2nico \xE9 acumulado.
Flywheel girando: 10+ vendas/semana constantes, rank org\xE2nico subindo, ACOS caindo progressivamente, vendas n\xE3o atribu\xEDdas a ads come\xE7ando a aparecer.

\u2501\u2501\u2501 SA\xDADE DO AN\xDANCIO (EDS) \u2501\u2501\u2501
Fatores que determinam a sa\xFAde: qualidade das fotos, completude dos atributos, t\xEDtulo com keywords, avalia\xE7\xF5es (m\xEDn. 4.0\u2605), taxa de convers\xE3o hist\xF3rica, velocidade de resposta, taxa de cancelamento, estoque dispon\xEDvel.
Ads em produto com sa\xFAde baixa = voc\xEA paga mais CPC pela mesma posi\xE7\xE3o. Ficha que n\xE3o converte sem ads vai piorar com ads \u2014 s\xF3 custa mais.

CHECKLIST EDS \u2014 ANTES DE QUALQUER CAMPANHA:
\u25A1 T\xEDtulo: keyword principal no in\xEDcio, 60+ caracteres
\u25A1 Fotos: m\xEDnimo 6, capa sem texto/logo, produto no corpo, ilumina\xE7\xE3o limpa, cada varia\xE7\xE3o com foto pr\xF3pria
\u25A1 Atributos 100% preenchidos: G\xEAnero, Tecido (Suede/Malha/Viscolycra/Microfibra), Tamanho (P M G GG XG), Cor, Ocasi\xE3o, Esta\xE7\xE3o, Tipo
\u25A1 Descri\xE7\xE3o: medidas, composi\xE7\xE3o, guia de tamanhos
\u25A1 Avalia\xE7\xF5es: m\xEDnimo 3\u20135 antes de investir em ads
\u25A1 Pre\xE7o: dentro da faixa competitiva da categoria
\u25A1 Estoque: > 10 unidades dispon\xEDveis
\u25A1 GTIN: preencher se tiver EAN/GS1; se n\xE3o tiver, declarar "N\xE3o possui" \u2014 nunca em branco

\u2501\u2501\u2501 ALOCA\xC7\xC3O DE BUDGET \u2501\u2501\u2501
\u2192 70% para os 3\u20135 produtos campe\xF5es (flywheel j\xE1 girando)
\u2192 20% para produtos em lan\xE7amento/escala (comprar velocidade inicial)
\u2192 10% para explora\xE7\xE3o via campanha autom\xE1tica (identificar pr\xF3ximos campe\xF5es)

\u2501\u2501\u2501 GEST\xC3O DE ESTOQUE \u2501\u2501\u2501
Produto sem estoque \xE9 penalizado \u2014 queda de rank pode levar semanas para se recuperar.
< 10 unidades: reduzir budget em 50%
< 5 unidades: pausar campanha (nunca excluir \u2014 preservar hist\xF3rico)
Reposi\xE7\xE3o chegou: reativar com budget gradual
Nunca excluir campanha pausada \u2014 hist\xF3rico acumulado tem valor

\u2501\u2501\u2501 M\xC9TRICAS-CHAVE \u2501\u2501\u2501
CTR baixo = problema na foto de capa ou t\xEDtulo, n\xE3o no CPC
Convers\xE3o baixa com CTR bom = problema na ficha (fotos, pre\xE7o, avalia\xE7\xF5es)
ACOS produto novo/escala: aceitar at\xE9 50\u201360% por 14 dias \u2014 \xE9 fase de compra de velocidade
ACOS produto estabelecido: trabalhar para 20\u201330%
ACOS muito baixo (< 10%): poss\xEDvel sub-investimento \u2014 pode estar perdendo posi\xE7\xE3o
Velocidade de vendas: m\xE9trica que o algoritmo mais valoriza \u2014 monitorar diariamente

\u2501\u2501\u2501 FRETE COMO FATOR DE CONVERS\xC3O \u2501\u2501\u2501
Velocidade de entrega impacta diretamente as vendas. Ponto de coleta aprovado pode triplicar vendas por reduzir prazo de entrega. Para produtos com frete complexo: modalidade ME1 permite integrar transportadoras pr\xF3prias com a plataforma. Frete deve ser facilitador, n\xE3o empec\xEDlio na jornada do comprador.

\u2501\u2501\u2501 O QUE VOC\xCA N\xC3O FAZ \u2501\u2501\u2501
- N\xE3o ativa ads em produto com ficha incompleta
- N\xE3o pausa campanha de produto campe\xE3o sem avaliar custo de perder a posi\xE7\xE3o org\xE2nica
- N\xE3o aumenta budget sem entender a fase do produto
- N\xE3o cria campanha manual sem dados da autom\xE1tica
- N\xE3o exclui campanhas pausadas
- N\xE3o trata ACOS alto em produto novo como erro
- N\xE3o ativa ads com estoque < 10 unidades sem alertar sobre o risco

Seja direta e espec\xEDfica com n\xFAmeros. Responda em portugu\xEAs do Brasil.`;
async function analyzeWithLLM2(data) {
  const compactItems = data.items.map((i) => ({
    id: i.id,
    title: i.title.slice(0, 60),
    price: i.price,
    stock: i.available_quantity,
    sold_total: i.sold_quantity,
    listing_type: i.listing_type_id,
    health: i.health
  }));
  const result = await invokeLLM({
    messages: [
      { role: "system", content: SYSTEM_PROMPT5 },
      {
        role: "user",
        content: `Avalie a performance da conta Feminnita no Mercado Livre com os dados abaixo e gere o relat\xF3rio completo.

**Per\xEDodo:** ${data.period}
**Vendedor:** ${data.sellerId}

**Resumo do per\xEDodo:**
- An\xFAncios ativos: ${data.summary.totalActiveItems}
- Unidades vendidas (30d): ${data.summary.totalSoldLast30d}
- Receita (30d): R$${data.summary.totalRevenueLast30d.toFixed(2)}
- Ticket m\xE9dio: R$${data.summary.avgOrderValue.toFixed(2)}
- Top produtos (IDs): ${data.summary.topSellingIds.join(", ") || "nenhum"}
- Sem vendas (IDs): ${data.summary.zeroSalesIds.join(", ") || "nenhum"}

**Listagens ativas:**
${JSON.stringify(compactItems, null, 2)}

Forne\xE7a:
1. Resumo executivo (2-3 frases)
2. An\xE1lise detalhada por produto/grupo
3. Alertas cr\xEDticos
4. Recomenda\xE7\xF5es priorizadas

Ao final, retorne JSON EXATO:
\`\`\`json
{
  "summary": "resumo em 1 frase",
  "analysis": "an\xE1lise completa em texto corrido",
  "recommendations": [
    {
      "priority": "alta",
      "campanha": "nome/id do produto",
      "titulo": "t\xEDtulo da recomenda\xE7\xE3o",
      "descricao": "descri\xE7\xE3o detalhada",
      "acao": "a\xE7\xE3o espec\xEDfica a tomar"
    }
  ]
}
\`\`\``
      }
    ],
    maxTokens: 4e3
  });
  const content = String(result.choices[0]?.message?.content || "");
  const jsonMatch = content.match(/```json\s*([\s\S]*?)```/);
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch[1]);
      if (parsed.analysis) return parsed;
    } catch {
    }
  }
  try {
    const parsed = JSON.parse(content);
    if (parsed.analysis) return parsed;
  } catch {
  }
  return {
    analysis: content,
    summary: "Avalia\xE7\xE3o conclu\xEDda \u2014 veja a an\xE1lise completa abaixo.",
    recommendations: []
  };
}
async function chatWithMLAgent(conversationHistory2, rawMetrics) {
  const result = await invokeLLM({
    messages: [
      {
        role: "system",
        content: SYSTEM_PROMPT5 + `

Dados da avalia\xE7\xE3o:
${rawMetrics}

Responda as d\xFAvidas sobre a performance ML de forma direta e pr\xE1tica.`
      },
      ...conversationHistory2.map((m) => ({ role: m.role, content: m.content }))
    ],
    maxTokens: 1024
  });
  const content = result.choices[0]?.message?.content;
  return typeof content === "string" ? content : "N\xE3o consegui processar. Tente novamente.";
}
async function runMLAdsEvaluation(evaluationId, account = "feminnita") {
  const db = await getDb();
  if (!db) throw new Error("Banco indispon\xEDvel");
  try {
    await db.update(mlAdsEvaluations).set({ status: "running" }).where(eq59(mlAdsEvaluations.id, evaluationId));
    if (!getMLToken(account)) {
      await db.update(mlAdsEvaluations).set({
        status: "error",
        errorMessage: `Token ML n\xE3o configurado para conta ${account}`,
        completedAt: /* @__PURE__ */ new Date()
      }).where(eq59(mlAdsEvaluations.id, evaluationId));
      return;
    }
    const mlData = await collectMLAdsData(account);
    const llmResult = await analyzeWithLLM2(mlData);
    await db.update(mlAdsEvaluations).set({
      status: "done",
      rawMetrics: JSON.stringify(mlData),
      analysis: llmResult.analysis,
      recommendations: JSON.stringify(llmResult.recommendations),
      summary: llmResult.summary,
      completedAt: /* @__PURE__ */ new Date()
    }).where(eq59(mlAdsEvaluations.id, evaluationId));
    console.log(
      `[MLAgent] Avalia\xE7\xE3o ${evaluationId} conclu\xEDda \u2014 ${mlData.items.length} itens, ${mlData.recentOrders.length} pedidos analisados`
    );
  } catch (err) {
    console.error(`[MLAgent] Erro na avalia\xE7\xE3o ${evaluationId}:`, err);
    await db.update(mlAdsEvaluations).set({
      status: "error",
      errorMessage: err.message?.slice(0, 499) || "Erro desconhecido",
      completedAt: /* @__PURE__ */ new Date()
    }).where(eq59(mlAdsEvaluations.id, evaluationId));
  }
}

