var mlAdsManagerRouter = router({
  /**
   * Retorna se a conta ML está conectada (token presente).
   */
  getAuthStatus: protectedProcedure.input(z58.object({ account: z58.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).query(async ({ input }) => {
    const acc = input?.account ?? "feminnita";
    async function testToken() {
      const token = acc === "fnt" ? process.env.ML_ACCESS_TOKEN_2 : process.env.ML_ACCESS_TOKEN_1;
      const envUserId2 = acc === "fnt" ? process.env.ML_USER_ID_2 : process.env.ML_USER_ID_1;
      if (!token) return { ok: false };
      try {
        const res = await fetch("https://api.mercadolibre.com/users/me", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (!res.ok) return { ok: false, userId: envUserId2 };
        const data = await res.json();
        return { ok: true, userId: String(data.id || envUserId2 || "") };
      } catch {
        return { ok: false, userId: envUserId2 };
      }
    }
    const first = await testToken();
    if (first.ok) return { connected: true, userId: first.userId, expired: false };
    const refreshed = await refreshMLToken(acc);
    if (refreshed) {
      const second = await testToken();
      if (second.ok) return { connected: true, userId: second.userId, expired: false };
    }
    const envUserId = acc === "fnt" ? process.env.ML_USER_ID_2 : process.env.ML_USER_ID_1;
    const hasToken = Boolean(acc === "fnt" ? process.env.ML_ACCESS_TOKEN_2 : process.env.ML_ACCESS_TOKEN_1);
    return { connected: false, userId: envUserId, expired: hasToken };
  }),
  /**
   * Dispara uma nova avaliação da conta ML Ads.
   */
  triggerEvaluation: protectedProcedure.input(z58.object({ account: z58.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).mutation(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) throw new Error("Banco indispon\xEDvel");
    const account = input?.account ?? "feminnita";
    const result = await db.insert(mlAdsEvaluations).values({
      userId: ctx.user.id,
      account,
      status: "pending",
      triggeredAt: /* @__PURE__ */ new Date(),
      createdAt: /* @__PURE__ */ new Date()
    });
    const evaluationId = Array.isArray(result) ? result[0].insertId : result.insertId;
    runMLAdsEvaluation(evaluationId, account).catch(
      (err) => console.error("[MLAdsManager] Erro em runMLAdsEvaluation:", err)
    );
    return { evaluationId, status: "pending" };
  }),
  /**
   * Busca o estado atual de uma avaliação específica (polling).
   */
  getEvaluation: protectedProcedure.input(z58.object({ id: z58.number() })).query(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) throw new Error("Banco indispon\xEDvel");
    const rows = await db.select().from(mlAdsEvaluations).where(
      and53(
        eq60(mlAdsEvaluations.id, input.id),
        eq60(mlAdsEvaluations.userId, ctx.user.id)
      )
    );
    if (!rows.length) throw new Error("Avalia\xE7\xE3o n\xE3o encontrada");
    const ev = rows[0];
    return {
      ...ev,
      rawMetrics: ev.rawMetrics ? JSON.parse(ev.rawMetrics) : null,
      recommendations: ev.recommendations ? JSON.parse(ev.recommendations) : []
    };
  }),
  /**
   * Lista todas as avaliações do usuário (histórico).
   */
  listEvaluations: protectedProcedure.input(z58.object({ account: z58.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).query(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) return [];
    const account = input?.account ?? "feminnita";
    return db.select({
      id: mlAdsEvaluations.id,
      account: mlAdsEvaluations.account,
      status: mlAdsEvaluations.status,
      summary: mlAdsEvaluations.summary,
      errorMessage: mlAdsEvaluations.errorMessage,
      triggeredAt: mlAdsEvaluations.triggeredAt,
      completedAt: mlAdsEvaluations.completedAt
    }).from(mlAdsEvaluations).where(and53(eq60(mlAdsEvaluations.userId, ctx.user.id), eq60(mlAdsEvaluations.account, account))).orderBy(desc30(mlAdsEvaluations.triggeredAt)).limit(10);
  }),
  /**
   * Busca campanhas ao vivo da ML Ads API.
   */
  listCampaigns: protectedProcedure.input(z58.object({ account: z58.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).query(async ({ input }) => {
    const acc = input?.account ?? "feminnita";
    const token = acc === "fnt" ? process.env.ML_ACCESS_TOKEN_2 : process.env.ML_ACCESS_TOKEN_1;
    if (!token) throw new Error("Token ML n\xE3o configurado para esta conta.");
    return collectMLAdsData(acc);
  }),
  /**
   * Envia uma mensagem de follow-up para o agente ML.
   */
  sendMessage: protectedProcedure.input(
    z58.object({
      evaluationId: z58.number(),
      message: z58.string().min(1).max(2e3)
    })
  ).mutation(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) throw new Error("Banco indispon\xEDvel");
    const ev = await db.select().from(mlAdsEvaluations).where(
      and53(
        eq60(mlAdsEvaluations.id, input.evaluationId),
        eq60(mlAdsEvaluations.userId, ctx.user.id)
      )
    );
    if (!ev.length || ev[0].status !== "done") {
      throw new Error("Avalia\xE7\xE3o n\xE3o encontrada ou ainda n\xE3o conclu\xEDda");
    }
    await db.insert(mlAdsEvaluationMessages).values({
      evaluationId: input.evaluationId,
      userId: ctx.user.id,
      role: "user",
      content: input.message,
      createdAt: /* @__PURE__ */ new Date()
    });
    const history = await db.select().from(mlAdsEvaluationMessages).where(eq60(mlAdsEvaluationMessages.evaluationId, input.evaluationId)).orderBy(mlAdsEvaluationMessages.createdAt);
    const reply = await chatWithMLAgent(
      history.map((m) => ({
        role: m.role,
        content: m.content
      })),
      ev[0].rawMetrics || "[]"
    );
    await db.insert(mlAdsEvaluationMessages).values({
      evaluationId: input.evaluationId,
      userId: ctx.user.id,
      role: "assistant",
      content: reply,
      createdAt: /* @__PURE__ */ new Date()
    });
    return { reply };
  }),
  /**
   * Retorna o status da sessão Playwright salva localmente.
   */
  getMLSessionStatus: protectedProcedure.input(z58.object({ account: z58.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).query(async ({ input }) => {
    const acc = input?.account ?? "feminnita";
    const { getMLSessionStatus: getMLSessionStatus2 } = await Promise.resolve().then(() => (init_ml_ads_browser_agent(), ml_ads_browser_agent_exports));
    return getMLSessionStatus2(acc);
  }),
  /**
   * Importa cookies de sessão ML copiados do browser do usuário.
   */
  uploadMLSession: protectedProcedure.input(z58.object({
    account: z58.enum(["feminnita", "fnt"]).default("feminnita"),
    cookies: z58.string().min(2)
  })).mutation(async ({ input }) => {
    let parsed;
    try {
      parsed = JSON.parse(input.cookies);
      if (!Array.isArray(parsed)) throw new Error("Deve ser um array JSON");
      if (parsed.length === 0) throw new Error("Array vazio");
    } catch (e) {
      throw new Error(`JSON inv\xE1lido: ${e.message}`);
    }
    const { importMLSession: importMLSession2 } = await Promise.resolve().then(() => (init_ml_ads_browser_agent(), ml_ads_browser_agent_exports));
    await importMLSession2(parsed, input.account);
    return { ok: true, count: parsed.length };
  }),
  /**
   * Lista mensagens de uma conversa.
   */
  getMessages: protectedProcedure.input(z58.object({ evaluationId: z58.number() })).query(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) return [];
    const ev = await db.select({ id: mlAdsEvaluations.id }).from(mlAdsEvaluations).where(
      and53(
        eq60(mlAdsEvaluations.id, input.evaluationId),
        eq60(mlAdsEvaluations.userId, ctx.user.id)
      )
    );
    if (!ev.length) return [];
    return db.select().from(mlAdsEvaluationMessages).where(eq60(mlAdsEvaluationMessages.evaluationId, input.evaluationId)).orderBy(mlAdsEvaluationMessages.createdAt);
  })
});

