var shopeeAdsManagerRouter = router({
  /**
   * Dispara nova avaliação Shopee Ads.
   */
  triggerEvaluation: protectedProcedure.input(z59.object({ account: z59.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).mutation(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) throw new Error("Banco indispon\xEDvel");
    const account = input?.account ?? "feminnita";
    const shopId = (account === "fnt" ? process.env.SHOPEE_SHOP_ID_2 : process.env.SHOPEE_SHOP_ID) || null;
    const result = await db.insert(shopeeAdsEvaluations).values({
      userId: ctx.user.id,
      account,
      shopId: shopId ?? void 0,
      status: "pending",
      triggeredAt: /* @__PURE__ */ new Date(),
      createdAt: /* @__PURE__ */ new Date()
    });
    const evaluationId = Array.isArray(result) ? result[0].insertId : result.insertId;
    runShopeeAdsEvaluation(evaluationId, account).catch(
      (err) => console.error("[ShopeeAdsManager] Erro em runShopeeAdsEvaluation:", err)
    );
    return { evaluationId, status: "pending" };
  }),
  /**
   * Busca estado de uma avaliação (polling).
   */
  getEvaluation: protectedProcedure.input(z59.object({ id: z59.number() })).query(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) throw new Error("Banco indispon\xEDvel");
    const rows = await db.select().from(shopeeAdsEvaluations).where(and54(eq62(shopeeAdsEvaluations.id, input.id), eq62(shopeeAdsEvaluations.userId, ctx.user.id)));
    if (!rows.length) throw new Error("Avalia\xE7\xE3o n\xE3o encontrada");
    const ev = rows[0];
    return {
      ...ev,
      rawMetrics: ev.rawMetrics ? JSON.parse(ev.rawMetrics) : null,
      recommendations: ev.recommendations ? JSON.parse(ev.recommendations) : []
    };
  }),
  /**
   * Lista todas as avaliações do usuário.
   */
  listEvaluations: protectedProcedure.input(z59.object({ account: z59.enum(["feminnita", "fnt"]).default("feminnita") }).optional()).query(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) return [];
    const account = input?.account ?? "feminnita";
    return db.select({
      id: shopeeAdsEvaluations.id,
      status: shopeeAdsEvaluations.status,
      summary: shopeeAdsEvaluations.summary,
      errorMessage: shopeeAdsEvaluations.errorMessage,
      triggeredAt: shopeeAdsEvaluations.triggeredAt,
      completedAt: shopeeAdsEvaluations.completedAt
    }).from(shopeeAdsEvaluations).where(and54(eq62(shopeeAdsEvaluations.userId, ctx.user.id), eq62(shopeeAdsEvaluations.account, account))).orderBy(desc31(shopeeAdsEvaluations.triggeredAt)).limit(20);
  }),
  /**
   * Anúncios ao vivo da Shopee API.
   */
  listAds: protectedProcedure.query(async () => {
    const shopId = process.env.SHOPEE_SHOP_ID;
    if (!shopId) throw new Error("Conta Shopee n\xE3o conectada");
    return collectShopeeAdsData();
  }),
  /**
   * Envia mensagem de follow-up para o agente Shopee.
   */
  sendMessage: protectedProcedure.input(z59.object({
    evaluationId: z59.number(),
    message: z59.string().min(1).max(2e3)
  })).mutation(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) throw new Error("Banco indispon\xEDvel");
    const ev = await db.select().from(shopeeAdsEvaluations).where(and54(eq62(shopeeAdsEvaluations.id, input.evaluationId), eq62(shopeeAdsEvaluations.userId, ctx.user.id)));
    if (!ev.length || ev[0].status !== "done") {
      throw new Error("Avalia\xE7\xE3o n\xE3o encontrada ou ainda n\xE3o conclu\xEDda");
    }
    await db.insert(shopeeAdsEvaluationMessages).values({
      evaluationId: input.evaluationId,
      userId: ctx.user.id,
      role: "user",
      content: input.message,
      createdAt: /* @__PURE__ */ new Date()
    });
    const history = await db.select().from(shopeeAdsEvaluationMessages).where(eq62(shopeeAdsEvaluationMessages.evaluationId, input.evaluationId)).orderBy(shopeeAdsEvaluationMessages.createdAt);
    const reply = await chatWithShopeeAgent(
      history.map((m) => ({ role: m.role, content: m.content })),
      ev[0].rawMetrics || "[]"
    );
    await db.insert(shopeeAdsEvaluationMessages).values({
      evaluationId: input.evaluationId,
      userId: ctx.user.id,
      role: "assistant",
      content: reply,
      createdAt: /* @__PURE__ */ new Date()
    });
    return { reply };
  }),
  /**
   * Lista mensagens de uma conversa.
   */
  getMessages: protectedProcedure.input(z59.object({ evaluationId: z59.number() })).query(async ({ ctx, input }) => {
    const db = await getDb();
    if (!db) return [];
    const ev = await db.select({ id: shopeeAdsEvaluations.id }).from(shopeeAdsEvaluations).where(and54(eq62(shopeeAdsEvaluations.id, input.evaluationId), eq62(shopeeAdsEvaluations.userId, ctx.user.id)));
    if (!ev.length) return [];
    return db.select().from(shopeeAdsEvaluationMessages).where(eq62(shopeeAdsEvaluationMessages.evaluationId, input.evaluationId)).orderBy(shopeeAdsEvaluationMessages.createdAt);
  }),
  /**
   * Status da conexão Shopee OAuth.
   */
  getAuthStatus: protectedProcedure.query(() => {
    const shopId = process.env.SHOPEE_SHOP_ID;
    const accessToken = process.env.SHOPEE_ACCESS_TOKEN;
    const connected = !!(shopId && accessToken);
    return { connected, shopId: shopId || void 0 };
  }),
  updateKnowledge: protectedProcedure.mutation(async () => {
    const summary = await updateShopeeKnowledge();
    return { ok: true, summary };
  })
});

