async function updateMarketKnowledge(domain) {
  const db = await getDb();
  if (!db) throw new Error("Database unavailable");
  const toUpdate = domain ? DOMAINS.filter((d) => d.key === domain) : DOMAINS;
  const updated = [];
  const errors = [];
  for (const d of toUpdate) {
    try {
      const result = await invokeLLM({
        messages: [{ role: "user", content: d.prompt }],
        maxTokens: 1200
      });
      const raw = String(result.choices[0]?.message?.content ?? "");
      const cleaned = raw.replace(/^```json\s*/i, "").replace(/```\s*$/, "").trim();
      const m = cleaned.match(/\{[\s\S]*\}/);
      const parsed = JSON.parse(m ? m[0] : cleaned);
      const period = (/* @__PURE__ */ new Date()).toISOString().split("T")[0];
      await db.insert(agentMemory).values({
        agentName: d.agentName,
        memoryType: "learning",
        period,
        content: JSON.stringify(parsed)
      });
      updated.push(d.key);
      console.log(`[KnowledgeUpdater] \u2713 ${d.key} atualizado`);
    } catch (err) {
      errors.push(`${d.key}: ${err.message}`);
      console.error(`[KnowledgeUpdater] \u2717 ${d.key}:`, err.message);
    }
  }
  return { updated, errors };
}
async function getLatestKnowledge(agentName) {
  try {
    const db = await getDb();
    if (!db) return null;
    const rows = await db.select().from(agentMemory).where(and55(eq63(agentMemory.agentName, agentName), eq63(agentMemory.memoryType, "learning"))).orderBy(desc32(agentMemory.createdAt)).limit(1);
    if (!rows.length) return null;
    return JSON.parse(rows[0].content);
  } catch {
    return null;
  }
}
async function getKnowledgeStatus() {
  const db = await getDb();
  if (!db) return [];
  return Promise.all(
    DOMAINS.map(async (d) => {
      const rows = await db.select().from(agentMemory).where(and55(eq63(agentMemory.agentName, d.agentName), eq63(agentMemory.memoryType, "learning"))).orderBy(desc32(agentMemory.createdAt)).limit(1);
      const lastUpdate = rows[0]?.createdAt ? new Date(rows[0].createdAt).toISOString() : null;
      const daysOld = lastUpdate ? Math.floor((Date.now() - new Date(lastUpdate).getTime()) / 864e5) : 999;
      return { domain: d.key, lastUpdate, daysOld };
    })
  );
}

// server/agents/tiktok-shop-agent.ts
async function fetchProducts() {
  try {
    const data = await tiktokShopPost("/product/202309/products/search", { page_size: "50" }, { status: "ACTIVATE" });
    console.log("[TikTokShopAgent] Resposta produtos:", JSON.stringify(data).slice(0, 300));
    const products = data?.data?.products || [];
    return products.map((p) => ({
      id: p.id,
      title: p.title || `Produto ${p.id}`,
      status: p.status || "ACTIVE",
      price: p.skus?.[0]?.price?.sale_price || 0,
      stock: p.skus?.reduce((acc, s) => acc + (s.stock?.available_stock || 0), 0) || 0
    }));
  } catch (err) {
    console.warn("[TikTokShopAgent] Erro ao buscar produtos:", err);
    return [];
  }
}
async function fetchOrders2() {
  try {
    const now = Math.floor(Date.now() / 1e3);
    const from = now - 30 * 24 * 60 * 60;
    const data = await tiktokShopPost("/order/202309/orders/search", { page_size: "50" }, {
      create_time_from: from,
      create_time_to: now,
      order_status: "COMPLETED"
    });
    console.log("[TikTokShopAgent] Resposta pedidos:", JSON.stringify(data).slice(0, 300));
    if (data?.code === 105005) {
      console.warn("[TikTokShopAgent] Sem escopo para pedidos \u2014 adicionar seller.order no Partner Center");
      return [];
    }
    const orders = data?.data?.orders || [];
    return orders.map((o) => ({
      id: o.id,
      status: o.status,
      amount: o.payment?.total_amount || 0,
      date: new Date((o.create_time || 0) * 1e3).toLocaleDateString("pt-BR")
    }));
  } catch (err) {
    console.warn("[TikTokShopAgent] Erro ao buscar pedidos:", err);
    return [];
  }
}
async function collectTiktokShopData() {
  const shopId = process.env.TIKTOK_SHOP_ID || process.env.TIKTOK_ADS_APP_ID || "";
  const [products, orders] = await Promise.all([
    fetchProducts(),
    fetchOrders2()
  ]);
  const totalRevenue30d = orders.reduce((acc, o) => acc + o.amount, 0);
  const avgOrderValue = orders.length ? totalRevenue30d / orders.length : 0;
  const period = `${new Date(Date.now() - 30 * 24 * 60 * 60 * 1e3).toLocaleDateString("pt-BR")} \u2014 ${(/* @__PURE__ */ new Date()).toLocaleDateString("pt-BR")} (30 dias)`;
  return {
    products,
    orders: orders.slice(0, 20),
    shopId,
    period,
    summary: {
      totalActiveProducts: products.length,
      totalOrders30d: orders.length,
      totalRevenue30d,
      avgOrderValue
    }
  };
}
