async function chatWithTiktokShopAgent(history, rawMetrics) {
  const systemPrompt = await buildSystemPrompt2();
  const metricsContext = rawMetrics ? `

Dados da loja analisada:
${rawMetrics}` : "";
  const result = await invokeLLM({
    messages: [
      { role: "system", content: systemPrompt + metricsContext },
      ...history
    ],
    maxTokens: 2e3
  });
  return String(
    result.choices[0]?.message?.content || "N\xE3o consegui processar sua pergunta."
  );
}

