async function runLunaEvaluation(evaluationId, account = "feminnita") {
  const db = await getDb();
  if (!db) throw new Error("Banco indispon\xEDvel");
  try {
    await db.update(tiktokTeamEvaluations).set({ status: "running" }).where(eq67(tiktokTeamEvaluations.id, evaluationId));
    const systemPrompt = await buildLunaPrompt(account);
    const result = await invokeLLM({
      messages: [
        { role: "system", content: systemPrompt },
        {
          role: "user",
          content: `Fa\xE7a uma auditoria completa de TikTok Ads para a Feminnita (pijamas atacado, ticket R$400, meta R$100K GMV/m\xEAs).

Analise e entregue plano de a\xE7\xE3o para:
1. Estrutura de campanhas recomendada (objetivos, adsets, criativos)
2. P\xFAblicos priorit\xE1rios (LAL, interesses, Custom Audience)
3. Formatos de criativo que convertem para pijamas atacado no TikTok
4. Budget sugerido por fase (testes \u2192 escala)
5. KPIs e metas para os pr\xF3ximos 30 dias
6. Spark Ads: quais conte\xFAdos org\xE2nicos impulsionar

Retorne JSON:
\`\`\`json
{
  "summary": "diagn\xF3stico em 1 frase com n\xFAmero concreto",
  "analysis": "an\xE1lise completa e plano de a\xE7\xE3o",
  "recommendations": [
    { "priority": "alta", "titulo": "t\xEDtulo", "descricao": "descri\xE7\xE3o", "acao": "a\xE7\xE3o concreta com KPI e prazo" }
  ],
  "creativeBriefs": [
    {
      "publico": "Revendedora Aut\xF4noma",
      "formato": "In-Feed Video 9:16",
      "hook": "Primeiros 2 segundos: texto na tela + movimento",
      "roteiro": "estrutura do v\xEDdeo: gancho \u2192 conte\xFAdo \u2192 CTA",
      "som": "tipo de som TikTok sugerido (trending/comercial)",
      "duracao": "segundos ideais",
      "cta": "bot\xE3o e copy de CTA",
      "sparkAds": "pode ser usado como Spark Ad? Por qu\xEA?"
    }
  ]
}
\`\`\``
        }
      ],
      maxTokens: 4e3
    });
    const content = String(result.choices[0]?.message?.content || "");
    let summary = "An\xE1lise TikTok Ads conclu\xEDda";
    let analysis = content;
    let recommendations = [];
    let creativeBriefs = [];
    const jsonMatch = content.match(/```json\s*([\s\S]*?)```/);
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[1]);
        summary = parsed.summary || summary;
        analysis = parsed.analysis || content.replace(/```json[\s\S]*?```/g, "").trim();
        recommendations = parsed.recommendations || [];
        creativeBriefs = parsed.creativeBriefs || [];
      } catch {
      }
    }
    await db.update(tiktokTeamEvaluations).set({
      status: "done",
      analysis,
      recommendations: JSON.stringify(recommendations),
      creativeBriefs: JSON.stringify(creativeBriefs),
      summary,
      completedAt: /* @__PURE__ */ new Date()
    }).where(eq67(tiktokTeamEvaluations.id, evaluationId));
    const period = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
    await saveMemory(AGENT_NAME2, "daily_analysis", period, { summary, highlights: recommendations.slice(0, 3).map((r) => r.titulo), alerts: [] });
  } catch (err) {
    await db.update(tiktokTeamEvaluations).set({
      status: "error",
      errorMessage: String(err?.message || err).slice(0, 500),
      completedAt: /* @__PURE__ */ new Date()
    }).where(eq67(tiktokTeamEvaluations.id, evaluationId));
    throw err;
  }
}
async function updateLunaKnowledge() {
  const systemPrompt = await buildLunaPrompt();
  const result = await invokeLLM({
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: "Gere um resumo semanal de estrat\xE9gia TikTok Ads para a Feminnita. Inclua: o que est\xE1 funcionando no TikTok Ads para moda atacado, benchmarks atuais, tend\xEAncias de criativo e recomenda\xE7\xF5es de a\xE7\xE3o para a pr\xF3xima semana. Formato: texto direto, sem JSON." }
    ],
    maxTokens: 1500
  });
  const summary = String(result.choices[0]?.message?.content || "");
  const period = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
  await saveMemory(AGENT_NAME2, "weekly_summary", period, { summary });
  return summary;
}
async function chatWithLuna(history, userName) {
  const systemPrompt = await buildLunaPrompt();
  const nameCtx = userName ? `
NOME DO USU\xC1RIO: Chame-o(a) de "${userName}" durante a conversa.` : "";
  const result = await invokeLLM({ messages: [{ role: "system", content: systemPrompt + nameCtx }, ...history], maxTokens: 2e3 });
  return String(result.choices[0]?.message?.content || "N\xE3o consegui processar.");
}

