async function runNinaEvaluation(evaluationId, account = "feminnita") {
  const db = await getDb();
  if (!db) throw new Error("Banco indispon\xEDvel");
  try {
    await db.update(tiktokTeamEvaluations).set({ status: "running" }).where(eq70(tiktokTeamEvaluations.id, evaluationId));
    const systemPrompt = await buildNinaPrompt(account);
    const result = await invokeLLM({
      messages: [
        { role: "system", content: systemPrompt },
        {
          role: "user",
          content: `Crie uma estrat\xE9gia completa de conte\xFAdo org\xE2nico TikTok para a Feminnita (pijamas atacado, meta crescer conta e gerar leads B2B).

Entregue:
1. Calend\xE1rio de conte\xFAdo: 30 ideias de v\xEDdeos (tema, formato, \xE1udio sugerido)
2. 5 scripts completos de v\xEDdeos (hook + desenvolvimento + CTA)
3. Estrat\xE9gia de hashtags por tipo de conte\xFAdo
4. Metas de crescimento: views, seguidores, leads por m\xEAs
5. Como usar trends sem perder identidade de marca

Retorne JSON:
\`\`\`json
{
  "summary": "diagn\xF3stico em 1 frase com meta concreta",
  "analysis": "estrat\xE9gia completa detalhada",
  "recommendations": [
    { "priority": "alta", "titulo": "t\xEDtulo", "descricao": "descri\xE7\xE3o", "acao": "a\xE7\xE3o com prazo e KPI" }
  ],
  "creativeBriefs": [
    {
      "publico": "p\xFAblico que o v\xEDdeo vai alcan\xE7ar",
      "formato": "tipo de v\xEDdeo TikTok",
      "hook": "primeiros 2 segundos exatos",
      "roteiro": "estrutura completa do v\xEDdeo",
      "som": "\xE1udio/trend sugerido",
      "duracao": "dura\xE7\xE3o ideal em segundos",
      "cta": "call-to-action final",
      "observacoes": "hashtags, hor\xE1rio de postagem, notas de produ\xE7\xE3o"
    }
  ]
}
\`\`\``
        }
      ],
      maxTokens: 4e3
    });
    const content = String(result.choices[0]?.message?.content || "");
    let summary = "Estrat\xE9gia org\xE2nica TikTok conclu\xEDda";
    let analysis = content;
    let recommendations = [];
    let creativeBriefs = [];
    const jsonMatch = content.match(/```json\s*([\s\S]*?)```/);
    if (jsonMatch) {
      try {
        const parsed = JSON.parse(jsonMatch[1]);
        summary = parsed.summary || summary;
        analysis = parsed.analysis || content.replace(/```json[\s\S]*?```/g, "").trim();
        recommendations = parsed.recommendations || [];
        creativeBriefs = parsed.creativeBriefs || [];
      } catch {
      }
    }
    await db.update(tiktokTeamEvaluations).set({
      status: "done",
      analysis,
      recommendations: JSON.stringify(recommendations),
      creativeBriefs: JSON.stringify(creativeBriefs),
      summary,
      completedAt: /* @__PURE__ */ new Date()
    }).where(eq70(tiktokTeamEvaluations.id, evaluationId));
    const period = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
    await saveMemory(AGENT_NAME5, "daily_analysis", period, { summary, highlights: recommendations.slice(0, 3).map((r) => r.titulo), alerts: [] });
  } catch (err) {
    await db.update(tiktokTeamEvaluations).set({
      status: "error",
      errorMessage: String(err?.message || err).slice(0, 500),
      completedAt: /* @__PURE__ */ new Date()
    }).where(eq70(tiktokTeamEvaluations.id, evaluationId));
    throw err;
  }
}
async function updateNinaKnowledge() {
  const systemPrompt = await buildNinaPrompt();
  const result = await invokeLLM({
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: "Gere um resumo semanal sobre conte\xFAdo org\xE2nico TikTok para a Feminnita. Trends da semana para aproveitar, o que est\xE1 performando no nicho de moda/atacado, algoritmo e recomenda\xE7\xF5es de conte\xFAdo para os pr\xF3ximos 7 dias." }
    ],
    maxTokens: 1500
  });
  const summary = String(result.choices[0]?.message?.content || "");
  const period = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
  await saveMemory(AGENT_NAME5, "weekly_summary", period, { summary });
  return summary;
}
async function chatWithNina(history, userName) {
  const systemPrompt = await buildNinaPrompt();
  const nameCtx = userName ? `
NOME DO USU\xC1RIO: Chame-o(a) de "${userName}" durante a conversa.` : "";
  const result = await invokeLLM({ messages: [{ role: "system", content: systemPrompt + nameCtx }, ...history], maxTokens: 2e3 });
  return String(result.choices[0]?.message?.content || "N\xE3o consegui processar.");
}

