async function generateVideoFromImages(params) {
  const { imageUrls, hookText = "", ctaText = "", durationPerImage = 4, dubbing = false, voiceId } = params;
  const tmpDir = await fs8.mkdtemp(path8.join(os.tmpdir(), "feminnita-vid-"));
  try {
    const uploadsDir = path8.resolve(process.cwd(), "uploads");
    const imagePaths = [];
    for (let i = 0; i < imageUrls.length; i++) {
      const url = imageUrls[i];
      let buf;
      let ext = ".jpg";
      if (url.startsWith("/uploads/")) {
        const localPath = path8.join(uploadsDir, path8.basename(url));
        buf = await fs8.readFile(localPath);
        const localExt = path8.extname(url).toLowerCase();
        if (localExt) ext = localExt;
      } else {
        const res = await fetch(url);
        if (!res.ok) throw new Error(`Imagem ${i + 1} n\xE3o p\xF4de ser baixada (${res.status})`);
        buf = Buffer.from(await res.arrayBuffer());
        const ct = res.headers.get("content-type") || "image/jpeg";
        ext = ct.includes("png") ? ".png" : ct.includes("webp") ? ".webp" : ".jpg";
      }
      const imgPath = path8.join(tmpDir, `img${i}${ext}`);
      await fs8.writeFile(imgPath, buf);
      imagePaths.push(imgPath);
    }
    const outputPath = path8.join(tmpDir, "output.mp4");
    const totalDuration = imagePaths.length * durationPerImage;
    let audioPath;
    if (dubbing && (hookText || ctaText)) {
      try {
        const dubbingText = [hookText, ctaText].filter(Boolean).join(". ");
        const audioBuffer = await textToSpeech(dubbingText, void 0, voiceId);
        audioPath = path8.join(tmpDir, "dubbing.mp3");
        await fs8.writeFile(audioPath, audioBuffer);
      } catch (err) {
        console.warn("[VideoGenerator] Dublagem falhou, gerando sem \xE1udio:", err.message);
        audioPath = void 0;
      }
    }
    let rendered = false;
    if (hookText || ctaText) {
      try {
        await renderWithText({ imagePaths, hookText, ctaText, durationPerImage, totalDuration, outputPath, audioPath });
        rendered = true;
      } catch {
      }
    }
    if (!rendered) {
      await renderSlideshow({ imagePaths, durationPerImage, outputPath, audioPath });
    }
    await fs8.mkdir(uploadsDir, { recursive: true });
    const filename = `${Date.now()}-${crypto10.randomBytes(8).toString("hex")}.mp4`;
    const destPath = path8.join(uploadsDir, filename);
    await fs8.copyFile(outputPath, destPath);
    return `/uploads/${filename}`;
  } finally {
    await fs8.rm(tmpDir, { recursive: true, force: true }).catch(() => {
    });
  }
}
function esc(text3) {
  return text3.replace(/\\/g, "\\\\").replace(/'/g, "\\'").replace(/:/g, "\\:").replace(/[[\]]/g, "").slice(0, 70);
}
function buildScaleFilters(n) {
  const filters = [];
  for (let i = 0; i < n; i++) {
    filters.push(
      `[${i}:v]scale=1080:1920:force_original_aspect_ratio=increase,crop=1080:1920,setsar=1,setpts=PTS-STARTPTS[v${i}]`
    );
  }
  const concatIn = Array.from({ length: n }, (_, i) => `[v${i}]`).join("");
  filters.push(`${concatIn}concat=n=${n}:v=1:a=0[base]`);
  return filters;
}
function runCommand(cmd, outputPath, hasAudio, totalDuration) {
  return new Promise((resolve2, reject) => {
    const outOpts = ["-c:v", "libx264", "-preset", "fast", "-crf", "23", "-pix_fmt", "yuv420p", "-r", "30", `-t ${totalDuration}`];
    if (hasAudio) {
      outOpts.push("-c:a", "aac", "-b:a", "128k", "-shortest");
    } else {
      outOpts.push("-an");
    }
    cmd.outputOptions(outOpts).output(outputPath).on("end", () => resolve2()).on("error", (err) => reject(err)).run();
  });
}
async function renderWithText(opts) {
  const { imagePaths, hookText, ctaText, durationPerImage, totalDuration, outputPath, audioPath } = opts;
  const n = imagePaths.length;
  let cmd = ffmpegLib();
  for (const p of imagePaths) {
    cmd = cmd.input(p).inputOptions([`-loop 1`, `-t ${durationPerImage}`]);
  }
  if (audioPath) cmd = cmd.input(audioPath);
  const filters = buildScaleFilters(n);
  const textParts = [];
  if (hookText) {
    textParts.push(
      `drawtext=text='${esc(hookText)}':fontsize=54:fontcolor=white:shadowcolor=black@0.85:shadowx=3:shadowy=3:x=(w-text_w)/2:y=h*0.12:enable='between(t,0,3)'`
    );
  }
  if (ctaText) {
    const t0 = Math.max(0, totalDuration - 3);
    textParts.push(
      `drawtext=text='${esc(ctaText)}':fontsize=54:fontcolor=white:shadowcolor=black@0.85:shadowx=3:shadowy=3:x=(w-text_w)/2:y=h*0.84:enable='between(t,${t0},${totalDuration})'`
    );
  }
  if (textParts.length > 0) {
    filters.push(`[base]${textParts.join(",")}[out]`);
  } else {
    filters.push(`[base]copy[out]`);
  }
  await runCommand(cmd.complexFilter(filters, "out"), outputPath, !!audioPath, totalDuration);
}
async function renderSlideshow(opts) {
  const { imagePaths, durationPerImage, outputPath, audioPath } = opts;
  const n = imagePaths.length;
  const totalDuration = n * durationPerImage;
  let cmd = ffmpegLib();
  for (const p of imagePaths) {
    cmd = cmd.input(p).inputOptions([`-loop 1`, `-t ${durationPerImage}`]);
  }
  if (audioPath) cmd = cmd.input(audioPath);
  const filters = buildScaleFilters(n);
  filters.push(`[base]copy[out]`);
  await runCommand(cmd.complexFilter(filters, "out"), outputPath, !!audioPath, totalDuration);
}

// server/services/minimax.ts
var API_KEY = process.env.MINIMAX_API_KEY || "";
var GROUP_ID = process.env.MINIMAX_GROUP_ID || "";
var BASE = "https://api.minimaxi.chat";
async function submitVideoTask(params) {
  if (!API_KEY) throw new Error("MINIMAX_API_KEY n\xE3o configurado");
  if (!GROUP_ID) throw new Error("MINIMAX_GROUP_ID n\xE3o configurado");
  const body = {
    model: params.model || "video-01",
    prompt: params.prompt || ""
  };
  if (params.imageUrl.startsWith("data:")) {
    body.first_frame_image = params.imageUrl;
  } else {
    body.first_frame_image = params.imageUrl;
  }
  const res = await fetch(`${BASE}/v1/video_generation?GroupId=${GROUP_ID}`, {
    method: "POST",
    headers: {
      "Authorization": `Bearer ${API_KEY}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(body)
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`MiniMax submit error ${res.status}: ${err}`);
  }
  const data = await res.json();
  if (data.base_resp?.status_code !== 0) {
    throw new Error(`MiniMax error: ${data.base_resp?.status_msg}`);
  }
  return data.task_id;
}
async function queryVideoTask(taskId) {
  if (!API_KEY) throw new Error("MINIMAX_API_KEY n\xE3o configurado");
  const res = await fetch(`${BASE}/v1/query/video_generation?task_id=${taskId}&GroupId=${GROUP_ID}`, {
    headers: { "Authorization": `Bearer ${API_KEY}` }
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`MiniMax query error ${res.status}: ${err}`);
  }
  const data = await res.json();
  if (data.base_resp?.status_code !== 0) {
    throw new Error(`MiniMax query error: ${data.base_resp?.status_msg}`);
  }
  const status = data.status;
  if (status === "Success") {
    return { status: "done", fileId: data.file_id };
  }
  if (status === "Fail") {
    return { status: "error", error: data.base_resp?.status_msg || "Gera\xE7\xE3o falhou" };
  }
  return { status: "processing" };
}
async function getVideoDownloadUrl(fileId) {
  if (!API_KEY) throw new Error("MINIMAX_API_KEY n\xE3o configurado");
  const res = await fetch(`${BASE}/v1/files/retrieve?file_id=${fileId}&GroupId=${GROUP_ID}`, {
    headers: { "Authorization": `Bearer ${API_KEY}` }
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`MiniMax file retrieve error ${res.status}: ${err}`);
  }
  const data = await res.json();
  if (data.base_resp?.status_code !== 0) {
    throw new Error(`MiniMax file error: ${data.base_resp?.status_msg}`);
  }
  return data.file?.download_url;
}
async function generateVideoFromImage(params, onProgress) {
  const fs15 = await import("fs/promises");
  const path16 = await import("path");
  const crypto15 = await import("crypto");
  onProgress?.("Enviando para MiniMax...");
  const taskId = await submitVideoTask(params);
  onProgress?.(`Task criada: ${taskId}`);
  const maxAttempts = 60;
  for (let i = 0; i < maxAttempts; i++) {
    await sleep(5e3);
    const result = await queryVideoTask(taskId);
    onProgress?.(`Status: ${result.status} (tentativa ${i + 1})`);
    if (result.status === "error") {
      throw new Error(result.error || "Gera\xE7\xE3o falhou no MiniMax");
    }
    if (result.status === "done" && result.fileId) {
      onProgress?.("Obtendo URL do v\xEDdeo...");
      const downloadUrl = await getVideoDownloadUrl(result.fileId);
      onProgress?.("Baixando v\xEDdeo...");
      const videoRes = await fetch(downloadUrl);
      if (!videoRes.ok) throw new Error(`Erro ao baixar v\xEDdeo: ${videoRes.status}`);
      const buf = Buffer.from(await videoRes.arrayBuffer());
      const uploadsDir = path16.default.resolve(process.cwd(), "uploads");
      await fs15.default.mkdir(uploadsDir, { recursive: true });
      const filename = `${Date.now()}-${crypto15.default.randomBytes(8).toString("hex")}.mp4`;
      const destPath = path16.default.join(uploadsDir, filename);
      await fs15.default.writeFile(destPath, buf);
      onProgress?.(`V\xEDdeo salvo: /uploads/${filename}`);
      return `/uploads/${filename}`;
    }
  }
  throw new Error("Timeout: MiniMax demorou mais de 5 minutos");
}
function sleep(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

// server/services/google-veo.ts
var API_KEY2 = process.env.GOOGLE_AI_API_KEY || "";
var BASE2 = "https://generativelanguage.googleapis.com/v1beta";
var MODEL = "veo-3.1-generate-preview";
async function submitVeoTask(params) {
  if (!API_KEY2) throw new Error("GOOGLE_AI_API_KEY n\xE3o configurado");
  const resolution = params.resolution || "1080p";
  const durationSeconds = params.durationSeconds || "8";
  const { imageBase64, mimeType } = await readImageAsBase64(params.imageUrl);
  const body = {
    instances: [{
      prompt: params.prompt || "A person wearing the clothing moves naturally",
      image: {
        inlineData: {
          mimeType,
          data: imageBase64
        }
      }
    }],
    parameters: {
      aspectRatio: "9:16",
      resolution,
      durationSeconds
    }
  };
  const res = await fetch(`${BASE2}/models/${MODEL}:predictLongRunning`, {
    method: "POST",
    headers: {
      "x-goog-api-key": API_KEY2,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(body)
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Veo submit error ${res.status}: ${err}`);
  }
  const data = await res.json();
  if (!data.name) throw new Error("Veo n\xE3o retornou operation name");
  return data.name;
}
async function pollVeoOperation(operationName) {
  const res = await fetch(`${BASE2}/${operationName}`, {
    headers: { "x-goog-api-key": API_KEY2 }
  });
  if (!res.ok) {
    const err = await res.text();
    throw new Error(`Veo poll error ${res.status}: ${err}`);
  }
  const data = await res.json();
  if (data.error) {
    return { done: true, error: data.error.message || "Erro desconhecido" };
  }
  if (!data.done) return { done: false };
  const samples = data.response?.generateVideoResponse?.generatedSamples;
  if (!samples?.length) return { done: true, error: "Nenhum v\xEDdeo gerado" };
  const videoUri = samples[0]?.video?.uri;
  return { done: true, videoUri };
}
async function generateVideoFromImageVeo(params, onProgress) {
  const fs15 = await import("fs/promises");
  const path16 = await import("path");
  const crypto15 = await import("crypto");
  onProgress?.("Enviando para Google Veo...");
  const operationName = await submitVeoTask(params);
  onProgress?.(`Opera\xE7\xE3o iniciada: ${operationName}`);
  const maxAttempts = 120;
  for (let i = 0; i < maxAttempts; i++) {
    await sleep2(5e3);
    const result = await pollVeoOperation(operationName);
    onProgress?.(`Aguardando Veo... tentativa ${i + 1}`);
    if (result.error) throw new Error(result.error);
    if (result.done && result.videoUri) {
      onProgress?.("Baixando v\xEDdeo do Google...");
      const videoRes = await fetch(result.videoUri);
      if (!videoRes.ok) throw new Error(`Erro ao baixar v\xEDdeo Veo: ${videoRes.status}`);
      const buf = Buffer.from(await videoRes.arrayBuffer());
      const uploadsDir = path16.default.resolve(process.cwd(), "uploads");
      await fs15.default.mkdir(uploadsDir, { recursive: true });
      const filename = `veo-${Date.now()}-${crypto15.default.randomBytes(8).toString("hex")}.mp4`;
      const destPath = path16.default.join(uploadsDir, filename);
      await fs15.default.writeFile(destPath, buf);
      onProgress?.(`V\xEDdeo salvo: /uploads/${filename}`);
      return `/uploads/${filename}`;
    }
  }
  throw new Error("Timeout: Google Veo demorou mais de 10 minutos");
}
async function readImageAsBase64(imageUrl) {
  const fs15 = await import("fs/promises");
  const path16 = await import("path");
  let buf;
  let mimeType = "image/jpeg";
  if (imageUrl.startsWith("/uploads/")) {
    const localPath = path16.default.join(path16.default.resolve(process.cwd(), "uploads"), path16.default.basename(imageUrl));
    buf = await fs15.default.readFile(localPath);
    const ext = path16.default.extname(imageUrl).toLowerCase();
    if (ext === ".png") mimeType = "image/png";
    else if (ext === ".webp") mimeType = "image/webp";
  } else {
    const res = await fetch(imageUrl);
    if (!res.ok) throw new Error(`N\xE3o foi poss\xEDvel baixar imagem: ${res.status}`);
    buf = Buffer.from(await res.arrayBuffer());
    const ct = res.headers.get("content-type") || "";
    if (ct.includes("png")) mimeType = "image/png";
    else if (ct.includes("webp")) mimeType = "image/webp";
  }
  return { imageBase64: buf.toString("base64"), mimeType };
}
function sleep2(ms) {
  return new Promise((r) => setTimeout(r, ms));
}

