var ML_BASE2 = "https://api.mercadolibre.com";
function getMLToken2(account = "feminnita") {
  return account === "fnt" ? process.env.ML_ACCESS_TOKEN_2 || "" : process.env.ML_ACCESS_TOKEN_1 || "";
}
function getUserId2(account = "feminnita") {
  return account === "fnt" ? process.env.ML_USER_ID_2 || "" : process.env.ML_USER_ID_1 || "";
}
async function mlGet(path16, token) {
  const res = await fetch(`${ML_BASE2}${path16}`, {
    headers: { Authorization: `Bearer ${token}` }
  });
  const data = await res.json();
  if (data.error) throw new Error(`ML API: ${data.message || data.error}`);
  return data;
}
async function mlPut(path16, body, token) {
  const res = await fetch(`${ML_BASE2}${path16}`, {
    method: "PUT",
    headers: {
      Authorization: `Bearer ${token}`,
      "Content-Type": "application/json"
    },
    body: JSON.stringify(body)
  });
  const data = await res.json();
  if (data.error) throw new Error(`ML API: ${data.message || data.error}`);
  return data;
}
async function listMLItems(account = "feminnita") {
  const token = getMLToken2(account);
  const userId = getUserId2(account);
  const label = account === "fnt" ? "Conta B (FNT)" : "Conta A (Feminnita)";
  console.log(`[GabiML] listMLItems \u2014 account=${account} userId=${userId} tokenLen=${token.length}`);
  if (!token || !userId) return "Erro: tokens ML n\xE3o configurados no servidor.";
  try {
    const search = await mlGet(`/users/${userId}/items/search?limit=50`, token);
    const allIds = search.results || [];
    const total = search.paging?.total || allIds.length;
    console.log(`[GabiML] listMLItems total=${total} ids=${allIds.length} userId=${userId}`);
    if (allIds.length === 0) return `Nenhum an\xFAncio encontrado em ${label}. Total na conta: ${total}.`;
    const top20 = allIds.slice(0, 20);
    const details = await mlGet(
      `/items?ids=${top20.join(",")}&attributes=id,title,status,price,available_quantity`,
      token
    );
    const lines = details.map((item) => {
      const d = item.body;
      if (!d || d.error) return null;
      const stock = d.available_quantity != null ? d.available_quantity : "?";
      return `\u2022 ID: ${d.id} | "${(d.title || "").slice(0, 55)}" | ${d.status} | R$${d.price} | Estoque: ${stock}`;
    }).filter(Boolean);
    return `AN\xDANCIOS ${label} (${total} total \u2014 exibindo ${top20.length}):
${lines.join("\n")}`;
  } catch (e) {
    return `Erro ao listar an\xFAncios: ${e.message}`;
  }
}
