async function executeMarketplaceAction(actionType, payload) {
  const { marketplace, account, targetId } = payload;
  const proposed = payload.proposedValue ?? "";
  if (marketplace === "ml") {
    switch (actionType) {
      case "ml_pause_campaign":
        return pauseAdsCampaign(targetId, account);
      case "ml_activate_campaign":
        return activateAdsCampaign(targetId, account);
      case "ml_update_budget":
        return updateAdsBudget(targetId, Number(proposed), account);
      case "ml_pause_item":
        return pauseMLItem(targetId, account);
      case "ml_activate_item":
        return activateMLItem(targetId, account);
      case "ml_update_price":
        return updateMLPrice(targetId, Number(proposed), account);
      case "ml_update_stock":
        return updateMLStock(targetId, Number(proposed), account);
      default:
        throw new Error(`Tipo de a\xE7\xE3o ML desconhecido: ${actionType}`);
    }
  }
  if (marketplace === "shopee") {
    const { shopeeRequest: shopeeRequest2 } = await Promise.resolve().then(() => (init_shopeeApi(), shopeeApi_exports));
    switch (actionType) {
      case "shopee_pause_campaign":
        await shopeeRequest2("POST", "/api/v2/ads/pause_campaign", { campaign_id_list: [Number(targetId)] }, account);
        return `Campanha Shopee ${targetId} pausada.`;
      case "shopee_activate_campaign":
        await shopeeRequest2("POST", "/api/v2/ads/enable_campaign", { campaign_id_list: [Number(targetId)] }, account);
        return `Campanha Shopee ${targetId} reativada.`;
      case "shopee_update_budget":
        await shopeeRequest2("POST", "/api/v2/ads/update_campaign_budget", { campaign_id: Number(targetId), budget: Number(proposed) }, account);
        return `Budget da campanha Shopee ${targetId} atualizado para R$${proposed}.`;
      case "shopee_update_roas":
        await shopeeRequest2("POST", "/api/v2/ads/update_campaign_roas", { campaign_id: Number(targetId), target_roas: Number(proposed) }, account);
        return `ROAS alvo da campanha Shopee ${targetId} atualizado para ${proposed}x.`;
      default:
        throw new Error(`Tipo de a\xE7\xE3o Shopee desconhecido: ${actionType}`);
    }
  }
  throw new Error(`Marketplace desconhecido: ${marketplace}`);
}
