async function fetchMetaAdsMetrics(days = 7) {
  const token = process.env.META_ACCESS_TOKEN;
  const adAccountId = process.env.META_AD_ACCOUNT_ID || "act_231648936319132";
  if (!token) {
    return { platform: "meta", available: false, reason: "META_ACCESS_TOKEN n\xE3o configurado" };
  }
  try {
    const params = new URLSearchParams({
      fields: "spend,impressions,clicks,ctr,cpc,actions",
      date_preset: days <= 7 ? "last_7d" : "last_30d",
      level: "account",
      access_token: token
    });
    const res = await fetch(`${GRAPH_BASE5}/${adAccountId}/insights?${params}`);
    if (!res.ok) {
      const err = await res.json();
      return { platform: "meta", available: false, reason: err.error?.message || `HTTP ${res.status}` };
    }
    const data = await res.json();
    const row = data.data?.[0] || {};
    const spend = parseFloat(row.spend || "0");
    const impressions = parseInt(row.impressions || "0");
    const clicks = parseInt(row.clicks || "0");
    const purchaseAction = (row.actions || []).find(
      (a) => a.action_type === "purchase" || a.action_type === "offsite_conversion.fb_pixel_purchase"
    );
    const conversions = purchaseAction ? parseFloat(purchaseAction.value || "0") : 0;
    const revenue = conversions * 400;
    const roas = spend > 0 && revenue > 0 ? revenue / spend : 0;
    const cpa = conversions > 0 ? spend / conversions : 0;
    return {
      platform: "meta",
      available: true,
      metrics: {
        platform: "meta",
        spend,
        impressions,
        clicks,
        conversions,
        revenue,
        roas: Math.round(roas * 100) / 100,
        ctr: parseFloat(row.ctr || "0"),
        cpc: parseFloat(row.cpc || "0"),
        cpa: Math.round(cpa * 100) / 100,
        currency: "BRL",
        periodDays: days,
        fetchedAt: (/* @__PURE__ */ new Date()).toISOString(),
        raw: row
      }
    };
  } catch (err) {
    return { platform: "meta", available: false, reason: err.message };
  }
}
