async function fetchMetaCampaigns() {
  const token = process.env.META_SYSTEM_USER_TOKEN || process.env.META_ACCESS_TOKEN || "";
  const accountId = process.env.META_AD_ACCOUNT_ID || "act_231648936319132";
  console.log(`[FernandaMeta] fetchMetaCampaigns \u2014 token length: ${token.length}, account: ${accountId}`);
  if (!token) return "Erro: META_ACCESS_TOKEN n\xE3o configurado no servidor.";
  try {
    const fields = "id,name,status,effective_status,daily_budget,lifetime_budget,objective,insights{spend,impressions,clicks,actions}";
    const url = `https://graph.facebook.com/v20.0/${accountId}/campaigns?fields=${fields}&date_preset=last_30d&access_token=${token}`;
    const res = await fetch(url);
    const data = await res.json();
    console.log(`[FernandaMeta] Resposta API: ${JSON.stringify(data).slice(0, 200)}`);
    if (data.error) return `Erro Meta API: ${data.error.message} (c\xF3digo ${data.error.code})`;
    const campaigns3 = data.data || [];
    if (campaigns3.length === 0) return "Nenhuma campanha encontrada na conta.";
    const lines = campaigns3.map((c) => {
      const budget = c.daily_budget ? `R$${(parseInt(c.daily_budget) / 100).toFixed(2)}/dia` : c.lifetime_budget ? `R$${(parseInt(c.lifetime_budget) / 100).toFixed(2)} total` : "sem or\xE7amento";
      const insight = c.insights?.data?.[0];
      const spend = insight ? ` | Gasto 30d: R$${parseFloat(insight.spend || "0").toFixed(2)}` : "";
      const purchases = insight?.actions?.find((a) => a.action_type === "purchase")?.value;
      const purchasesStr = purchases ? ` | Compras: ${purchases}` : "";
      return `\u2022 ID: ${c.id} | "${c.name}" | ${c.effective_status || c.status} | ${budget}${spend}${purchasesStr}`;
    });
    return `CAMPANHAS NA CONTA (${campaigns3.length} total):
${lines.join("\n")}`;
  } catch (e) {
    return `Erro ao buscar campanhas: ${e.message}`;
  }
}
async function executeSpecialistTool(name, input) {
  if (name === "search_web") {
    const result = await searchWeb(input.query, {
      days: input.days ?? 7,
      topic: "news",
      includeAnswer: true
    });
    const lines = [`Busca: "${result.query}"`];
    if (result.answer) lines.push(`S\xEDntese: ${result.answer}`);
    result.results.forEach((r, i) => {
      lines.push(`
[${i + 1}] ${r.title}`);
      if (r.publishedDate) lines.push(`Data: ${r.publishedDate}`);
      lines.push(r.content.slice(0, 400));
    });
    return lines.join("\n");
  }
  if (name === "get_sales_metrics") {
    const platforms = await fetchAllPlatformMetrics(input.days ?? 7);
    return formatPlatformSummary(platforms);
  }
  if (name === "meta_get_campaigns") {
    return fetchMetaCampaigns();
  }
  if (name === "meta_update_budget") {
    return executeMetaAction("meta_update_budget", {
      campaignId: input.campaignId,
      campaignName: input.campaignName,
      newDailyBudget: input.dailyBudgetReais
    });
  }
  if (name === "meta_pause_campaign") {
    return executeMetaAction("meta_pause_campaign", {
      campaignId: input.campaignId,
      campaignName: input.campaignName
    });
  }
  if (name === "meta_resume_campaign") {
    return executeMetaAction("meta_resume_campaign", {
      campaignId: input.campaignId,
      campaignName: input.campaignName
    });
  }
  if (name === "meta_create_campaign") {
    return executeMetaAction("meta_create_campaign", {
      name: input.name,
      objective: input.objective,
      dailyBudgetReais: input.dailyBudgetReais
    });
  }
  if (name === "meta_get_ad_sets") {
    return getAdSets(input.campaignId);
  }
  if (name === "meta_get_insights") {
    return getAccountInsights();
  }
  if (name === "meta_get_audiences") {
    return getCustomAudiences();
  }
  if (name === "meta_create_pixel_audience") {
    return createPixelAudience({
      name: input.name,
      pixelId: input.pixelId || process.env.META_PIXEL_ID || "",
      event: input.event,
      retentionDays: input.retentionDays,
      excludeEvent: input.excludeEvent
    });
  }
  if (name === "meta_create_ig_engagement_audience") {
    return createEngagementAudience({
      name: input.name,
      igUserId: input.igUserId || process.env.META_IG_ACCOUNT_ID || "",
      retentionDays: input.retentionDays
    });
  }
  if (name === "meta_duplicate_ad_set") {
    return duplicateAdSet({
      adSetId: input.adSetId,
      newName: input.newName,
      audienceIds: input.audienceIds,
      dailyBudgetReais: input.dailyBudgetReais
    });
  }
  if (name === "meta_update_ad_set_budget") {
    await updateAdSetBudget(input.adSetId, input.dailyBudgetReais);
    return `Or\xE7amento do conjunto ${input.adSetId} atualizado para R$${input.dailyBudgetReais}/dia.`;
  }
  return JSON.stringify({ error: `Ferramenta desconhecida: ${name}` });
}
