async function chatWithLuizaShopee(history, account = "feminnita", userName) {
  const systemPrompt = await buildLuizaShopeePrompt(account);
  const nameCtx = userName ? `
NOME DO USU\xC1RIO: Chame-o(a) de "${userName}" durante a conversa.` : "";
  const messages = history.map((m) => ({ role: m.role, content: m.content }));
  let response = await anthropic5.messages.create({
    model: "claude-sonnet-4-6",
    max_tokens: 2e3,
    system: systemPrompt + nameCtx,
    tools: LUIZA_SHOPEE_TOOLS,
    messages
  });
  let iterations = 0;
  while (response.stop_reason === "tool_use" && iterations < 6) {
    iterations++;
    const assistantContent = response.content;
    const toolUses = assistantContent.filter((b) => b.type === "tool_use");
    const toolResults = [];
    for (const toolUse of toolUses) {
      let result;
      try {
        const inp = toolUse.input;
        let call;
        if (toolUse.name === "execute_pending_actions") {
          call = (async () => {
            const db = await getDb();
            if (!db) return "Banco indispon\xEDvel \u2014 n\xE3o foi poss\xEDvel verificar as a\xE7\xF5es.";
            const { eq: eq113, and: and90 } = await import("drizzle-orm");
            const { agentActions: agentActionsTable2 } = await Promise.resolve().then(() => (init_schema(), schema_exports));
            const pending = await db.select().from(agentActionsTable2).where(and90(eq113(agentActionsTable2.agentName, "luiza"), eq113(agentActionsTable2.status, "pending")));
            if (pending.length === 0) return "Nenhuma a\xE7\xE3o pendente encontrada para executar.";
            const lines = pending.map((a) => `- ${a.title || a.actionType} [id=${a.id}]`);
            return `${pending.length} a\xE7\xE3o(\xF5es) enfileirada(s) para execu\xE7\xE3o via browser Shopee (pr\xF3ximos ~5 min):
${lines.join("\n")}

O executor em background abrir\xE1 o Seller Center, executar\xE1 cada a\xE7\xE3o e atualizar\xE1 o status no banco.`;
          })();
        } else if (toolUse.name === "get_shopee_campaigns") {
          call = withTimeout3((async () => {
            try {
              const data = await collectShopeeAdsData(account);
              const perf = data.adsPerformance;
              const lines = [
                `\u2501\u2501\u2501 PERFORMANCE GERAL (7 dias) \u2501\u2501\u2501`,
                `Gasto: R$${(perf?.expense || 0).toFixed(2)} | GMV: R$${(perf?.gmv || 0).toFixed(2)} | ROAS: ${(perf?.roas || 0).toFixed(2)}x`,
                `Cliques: ${perf?.clicks || 0} | CTR: ${(perf?.ctr || 0).toFixed(2)}% | CPC: R$${(perf?.cpc || 0).toFixed(2)}`,
                `Pedidos via Ads: ${perf?.orders || 0} | Saldo: R$${(perf?.balance || 0).toFixed(2)}`,
                ``,
                `\u2501\u2501\u2501 CAMPANHAS (${data.items.length} total, top 30 por gasto) \u2501\u2501\u2501`
              ];
              const sorted = [...data.items].sort((a, b) => (b.expense || 0) - (a.expense || 0));
              for (const c of sorted.slice(0, 30)) {
                const cc = c;
                const roas = cc.roas > 0 ? ` | ROAS ${cc.roas.toFixed(1)}x` : "";
                const spent = cc.expense > 0 ? ` | Gasto R$${cc.expense.toFixed(2)}` : " | sem gasto";
                const clk = cc.clicks > 0 ? ` | ${cc.clicks} cliques` : "";
                lines.push(`\u2022 [ID:${cc.id}] ${cc.name}${spent}${clk}${roas}`);
              }
              lines.push(``, `\u2501\u2501\u2501 PEDIDOS ORG\xC2NICOS (30d) \u2501\u2501\u2501`);
              lines.push(`Total: ${data.summary.totalOrders30d} | Receita: R$${data.summary.totalRevenue30d.toFixed(2)} | Ticket m\xE9dio: R$${data.summary.avgOrderValue.toFixed(2)}`);
              return lines.join("\n");
            } catch (e) {
              return `API Shopee Ads indispon\xEDvel: ${e.message}. Trabalhe com dados fornecidos pelo usu\xE1rio.`;
            }
          })(), 6e4, "get_shopee_campaigns");
        } else if (toolUse.name === "propose_shopee_actions") {
          call = (async () => {
            const db = await getDb();
            const today = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
            const rows = (inp.actions || []).map((a) => ({
              agentName: "luiza",
              date: today,
              title: String(a.title || ""),
              description: `${String(a.campaignName || "")} \u2014 ${String(a.currentValue || "")} \u2192 ${String(a.proposedValue || "")}`,
              actionType: String(a.actionType || "shopee_update_budget"),
              priority: ["alta", "media", "baixa"].includes(a.priority) ? a.priority : "media",
              estimatedImpact: String(a.reason || ""),
              status: "pending",
              payload: {
                marketplace: "shopee",
                account,
                campaignId: String(a.campaignId || ""),
                campaignName: String(a.campaignName || ""),
                currentValue: String(a.currentValue || ""),
                proposedValue: String(a.proposedValue || ""),
                action: String(a.actionType || "shopee_update_budget")
              }
            }));
            if (db && rows.length > 0) await db.insert(agentActions).values(rows);
            return `${rows.length} a\xE7\xE3o(\xF5es) salvas. Diga "pode continuar" ou "autorizo" para executar agora, ou acesse /acoes-agentes para revisar primeiro.`;
          })();
        } else {
          call = Promise.resolve(`Ferramenta desconhecida: ${toolUse.name}`);
        }
        result = await withTimeout3(call, 3e4, toolUse.name);
      } catch (e) {
        result = `Erro: ${e.message}`;
      }
      toolResults.push({ type: "tool_result", tool_use_id: toolUse.id, content: result });
    }
    messages.push({ role: "assistant", content: assistantContent });
    messages.push({ role: "user", content: toolResults });
    response = await anthropic5.messages.create({
      model: "claude-sonnet-4-6",
      max_tokens: 2e3,
      system: systemPrompt + nameCtx,
      tools: LUIZA_SHOPEE_TOOLS,
      messages
    });
  }
  const textBlocks = response.content.filter((b) => b.type === "text");
  let finalText = textBlocks.map((b) => b.text).join("\n");
  if (!finalText) {
    const forced = await anthropic5.messages.create({
      model: "claude-sonnet-4-6",
      max_tokens: 1e3,
      system: systemPrompt + nameCtx,
      messages: [...messages, { role: "assistant", content: response.content }]
    });
    finalText = forced.content.filter((b) => b.type === "text").map((b) => b.text).join("\n");
  }
  return finalText || "N\xE3o consegui processar.";
}
async function updateLuizaShopeeKnowledge() {
  const systemPrompt = await buildLuizaShopeePrompt();
  const result = await invokeLLM({
    messages: [
      { role: "system", content: systemPrompt },
      { role: "user", content: "Gere um resumo semanal de Shopee Ads para marcas de moda no Brasil. Inclua: benchmarks atuais de ROAS/CTR/CVR, mudan\xE7as recentes no algoritmo de an\xFAncios, tend\xEAncias de keywords para pijamas/moda feminina e recomenda\xE7\xF5es de a\xE7\xE3o para a pr\xF3xima semana." }
    ],
    maxTokens: 1500
  });
  const summary = String(result.choices[0]?.message?.content || "");
  const period = (/* @__PURE__ */ new Date()).toISOString().slice(0, 10);
  await saveMemory(AGENT_NAME8, "weekly_summary", period, { summary });
  return summary;
}

// server/routers/shopee-luiza.ts
init_db();
init_schema();
import { eq as eq86, and as and70, desc as desc47 } from "drizzle-orm";
var shopeeLuizaRouter = router({
  chat: protectedProcedure.input(z77.object({
    messages: z77.array(z77.object({
      role: z77.enum(["user", "assistant"]),
      content: z77.string()
    })).min(1).max(200),
    account: z77.enum(["feminnita", "fnt"]).default("feminnita"),
    conversationId: z77.number().optional()
  })).mutation(async ({ ctx, input }) => {
    const reply = await chatWithLuizaShopee(input.messages, input.account, ctx.user?.name ?? void 0);
    const db = await getDb();
    if (db) {
      const agentName = input.account === "fnt" ? "luiza_fnt" : "luiza";
      const userMessage = input.messages[input.messages.length - 1];
      let convId = input.conversationId;
      if (!convId) {
        const title = userMessage.content.slice(0, 60) + (userMessage.content.length > 60 ? "\u2026" : "");
        await db.insert(specialistConversations).values({
          userId: ctx.user.id,
          agentName,
          title
        });
        const [created] = await db.select().from(specialistConversations).where(and70(eq86(specialistConversations.userId, ctx.user.id), eq86(specialistConversations.agentName, agentName))).orderBy(desc47(specialistConversations.createdAt)).limit(1);
        convId = created.id;
      }
      await db.insert(specialistMessages).values({ conversationId: convId, role: "user", content: userMessage.content });
      await db.insert(specialistMessages).values({ conversationId: convId, role: "assistant", content: reply });
      if (convId) await db.update(specialistConversations).set({ updatedAt: /* @__PURE__ */ new Date() }).where(eq86(specialistConversations.id, convId));
      return { reply, conversationId: convId };
    }
    return { reply, conversationId: null };
  }),
  updateKnowledge: protectedProcedure.mutation(async () => {
    const summary = await updateLuizaShopeeKnowledge();
    return { summary };
  })
});

