import { z as z81 } from "zod";
import { TRPCError as TRPCError14 } from "@trpc/server";
import path9 from "path";
import fs9 from "fs";
var UPLOAD_DIR = path9.join(process.cwd(), "dist", "public", "chat-files");
var MAX_SIZE_MB = 10;
function ensureDir() {
  if (!fs9.existsSync(UPLOAD_DIR)) fs9.mkdirSync(UPLOAD_DIR, { recursive: true });
}
var chatUploadRouter = router({
  upload: protectedProcedure.input(z81.object({
    fileName: z81.string().max(200),
    mimeType: z81.string().max(100),
    fileData: z81.string()
    // base64
  })).mutation(async ({ input, ctx }) => {
    const buffer = Buffer.from(input.fileData, "base64");
    if (buffer.length > MAX_SIZE_MB * 1024 * 1024) {
      throw new TRPCError14({ code: "PAYLOAD_TOO_LARGE", message: `Arquivo muito grande (m\xE1x ${MAX_SIZE_MB}MB)` });
    }
    ensureDir();
    const ext = path9.extname(input.fileName).toLowerCase() || "";
    const safeName = `${Date.now()}-${ctx.user.id}-${Math.random().toString(36).slice(2)}${ext}`;
    const filePath = path9.join(UPLOAD_DIR, safeName);
    fs9.writeFileSync(filePath, buffer);
    return { url: `/chat-files/${safeName}`, fileName: input.fileName, mimeType: input.mimeType };
  })
});

// server/routers/hailuo-image.ts
import { z as z82 } from "zod";
var MINIMAX_BASE = "https://api.minimax.io/v1";
async function uploadReferenceImage(apiKey, base64, mimeType) {
  const buffer = Buffer.from(base64, "base64");
  const ext = mimeType.split("/")[1] || "jpg";
  const blob = new Blob([buffer], { type: mimeType });
  const form = new FormData();
  form.append("purpose", "retrieval");
  form.append("file", blob, `reference.${ext}`);
  const res = await fetch(`${MINIMAX_BASE}/files/upload`, {
    method: "POST",
    headers: { Authorization: `Bearer ${apiKey}` },
    body: form,
    signal: AbortSignal.timeout(3e4)
  });
  if (!res.ok) {
    const text3 = await res.text().catch(() => "");
    throw new Error(`Falha ao fazer upload da imagem de refer\xEAncia: ${text3.slice(0, 200)}`);
  }
  const data = await res.json();
  const fileId = data.file?.file_id;
  if (!fileId) throw new Error("MiniMax n\xE3o retornou file_id ap\xF3s upload.");
  return fileId;
}
var hailuoImageRouter = router({
  generate: protectedProcedure.input(z82.object({
    prompt: z82.string().min(1).max(1500),
    aspectRatio: z82.enum(["1:1", "16:9", "9:16", "4:3", "3:4", "3:2", "2:3", "21:9"]).default("1:1"),
    n: z82.number().min(1).max(4).default(1),
    quality: z82.enum(["1024", "2048", "4096"]).default("1024"),
    referenceImage: z82.object({
      base64: z82.string(),
      mimeType: z82.string()
    }).optional()
  })).mutation(async ({ input }) => {
    const apiKey = process.env.MINIMAX_API_KEY;
    if (!apiKey) throw new Error("MINIMAX_API_KEY n\xE3o configurado no servidor. Adicione a chave em Configura\xE7\xF5es \u2192 Integra\xE7\xF5es.");
    let subjectReference;
    if (input.referenceImage) {
      const fileId = await uploadReferenceImage(apiKey, input.referenceImage.base64, input.referenceImage.mimeType);
      subjectReference = [{ type: "character", image_file: { file_id: fileId } }];
    }
    const res = await fetch(`${MINIMAX_BASE}/image_generation`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        model: "image-01",
        prompt: input.prompt,
        aspect_ratio: input.aspectRatio,
        response_format: "url",
        n: input.n,
        prompt_optimizer: true,
        resolution: input.quality,
        ...subjectReference ? { subject_reference: subjectReference } : {}
      }),
      signal: AbortSignal.timeout(9e4)
    });
    if (!res.ok) {
      const text3 = await res.text().catch(() => "");
      throw new Error(`Hailuo API erro ${res.status}: ${text3.slice(0, 200)}`);
    }
    const data = await res.json();
    if (data.base_resp?.status_code !== 0) {
      const msg = data.base_resp?.status_msg || "Erro desconhecido";
      if (data.base_resp?.status_code === 1008) throw new Error("Saldo insuficiente na conta Hailuo/MiniMax.");
      if (data.base_resp?.status_code === 1002) throw new Error("Rate limit atingido. Tente novamente em instantes.");
      throw new Error(`Hailuo: ${msg}`);
    }
    const images = (data.data || []).map((img) => img.url).filter(Boolean);
    return { images };
  }),
  checkKey: protectedProcedure.query(() => {
    return { configured: !!process.env.MINIMAX_API_KEY };
  })
});

