init_sdk();
async function createContext(opts) {
  let user = null;
  let portalUser = null;
  try {
    user = await sdk.authenticateRequest(opts.req);
  } catch {
    user = null;
  }
  try {
    portalUser = await portalSdk.authenticatePortalRequest(opts.req);
  } catch {
    portalUser = null;
  }
  return { req: opts.req, res: opts.res, user, portalUser };
}

