// server/_core/deploy-webhook.ts
import { exec } from "child_process";
import * as fs12 from "fs";
import * as path13 from "path";
import * as crypto13 from "crypto";
var DEPLOY_SECRET = process.env.DEPLOY_SECRET || "";
function registerDeployWebhook(app) {
  app.post("/api/deploy", (req, res) => {
    if (DEPLOY_SECRET) {
      const sig = req.headers["x-hub-signature-256"];
      if (!sig) return res.status(401).json({ error: "Sem assinatura" });
      const hmac = crypto13.createHmac("sha256", DEPLOY_SECRET);
      hmac.update(req.rawBody || "");
      const expected = `sha256=${hmac.digest("hex")}`;
      if (!crypto13.timingSafeEqual(Buffer.from(sig), Buffer.from(expected))) {
        return res.status(401).json({ error: "Assinatura inv\xE1lida" });
      }
    }
    const event = req.headers["x-github-event"];
    const branch = req.body?.ref;
    if (event === "push" && branch && !branch.endsWith("/main")) {
      return res.json({ ok: true, msg: "Branch ignorada" });
    }
    const envVars = req.body?.envVars;
    if (envVars && typeof envVars === "object") {
      const envPath = path13.join("/var/www/feminnita-marketing", ".env");
      try {
        let content = fs12.existsSync(envPath) ? fs12.readFileSync(envPath, "utf8") : "";
        for (const [key, value] of Object.entries(envVars)) {
          if (!/^[A-Z_][A-Z0-9_]*$/.test(key)) continue;
          const line = `${key}=${value}`;
          const regex = new RegExp(`^${key}=.*$`, "m");
          if (regex.test(content)) {
            content = content.replace(regex, line);
          } else {
            content = content.trimEnd() + "\n" + line + "\n";
          }
        }
        fs12.writeFileSync(envPath, content, "utf8");
        console.log("[Deploy] .env atualizado:", Object.keys(envVars).join(", "));
      } catch (e) {
        console.error("[Deploy] Erro ao atualizar .env:", e.message);
      }
    }
    res.json({ ok: true, msg: "Deploy iniciado" });
    const deployCmd = "cd /var/www/feminnita-marketing && git pull && npm run build:full && (pm2 startOrRestart ecosystem.config.cjs --env production 2>/dev/null || pm2 restart feminnita-marketing --update-env 2>/dev/null || pm2 restart all 2>/dev/null)";
    exec(deployCmd, (err, stdout, stderr) => {
      if (err) {
        console.error("[Deploy] Erro:", err.message);
        console.error("[Deploy] stderr:", stderr.slice(-500));
      } else {
        console.log("[Deploy] Conclu\xEDdo:", stdout.slice(-300));
      }
    });
  });
  console.log("[Deploy] Webhook registrado em /api/deploy");
}

// server/_core/tray-webhook.ts
import crypto14 from "crypto";
async function fireMetaCAPIPurchase2(opts) {
  try {
    const pixelId = process.env.META_PIXEL_ID;
    const accessToken = process.env.META_SYSTEM_USER_TOKEN || process.env.META_ACCESS_TOKEN;
    if (!pixelId || !accessToken) return;
    const hashEmail2 = opts.email ? crypto14.createHash("sha256").update(opts.email.toLowerCase().trim()).digest("hex") : void 0;
    const hashPhone = opts.phone ? crypto14.createHash("sha256").update(opts.phone.replace(/\D/g, "")).digest("hex") : void 0;
    const userData = { country: ["br"] };
    if (hashEmail2) userData.em = [hashEmail2];
    if (hashPhone) userData.ph = [hashPhone];
    const payload = {
      data: [{
        event_name: "Purchase",
        event_time: Math.floor(Date.now() / 1e3),
        event_id: `tray_${opts.orderId}_${Date.now()}`,
        action_source: "website",
        user_data: userData,
        custom_data: {
          value: opts.value,
          currency: opts.currency ?? "BRL",
          order_id: opts.orderId
        }
      }]
    };
    const res = await fetch(
      `https://graph.facebook.com/v20.0/${pixelId}/events?access_token=${accessToken}`,
      { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(payload) }
    );
    const data = await res.json();
    console.log("[Tray\u2192MetaCAPI] Purchase enviado para pedido", opts.orderId, "\u2192", JSON.stringify(data));
  } catch (err) {
    console.error("[Tray\u2192MetaCAPI] Erro:", err.message);
  }
}
async function handleTrayWebhook(req, res) {
  try {
    const secret = process.env.TRAY_WEBHOOK_TOKEN;
    if (secret) {
      const token = req.headers["x-tray-token"];
      if (!token || token !== secret) {
        console.warn("[Tray Webhook] Token inv\xE1lido");
        return res.status(401).json({ error: "Unauthorized" });
      }
    }
    const body = req.body;
    console.log("[Tray Webhook] Recebido:", JSON.stringify(body));
    const tipo = body?.tipo;
    const acao = body?.acao ?? body?.action;
    const pedido = body?.pedido ?? body?.order;
    if (tipo !== "pedido" || !pedido) {
      return res.status(200).json({ ok: true, skipped: true });
    }
    const statusMapping = {
      novo: true,
      aprovado: true,
      pago: true,
      new: true,
      approved: true,
      paid: true
    };
    if (!statusMapping[acao]) {
      console.log(`[Tray Webhook] A\xE7\xE3o '${acao}' ignorada para CAPI`);
      return res.status(200).json({ ok: true, skipped: true });
    }
    const orderId = String(pedido.id ?? pedido.numero ?? "");
    const value = parseFloat(pedido.valor_total ?? pedido.total ?? 0);
    const email = pedido.cliente?.email ?? pedido.customer?.email ?? void 0;
    const phone = pedido.cliente?.celular ?? pedido.cliente?.telefone ?? pedido.customer?.phone ?? void 0;
    if (!orderId || value <= 0) {
      console.warn("[Tray Webhook] Pedido sem id/valor v\xE1lido, ignorando");
      return res.status(200).json({ ok: true, skipped: true });
    }
    await fireMetaCAPIPurchase2({ orderId, value, currency: "BRL", email, phone });
    return res.status(200).json({ ok: true });
  } catch (error) {
    console.error("[Tray Webhook] Erro:", error);
    return res.status(500).json({ error: "Internal error" });
  }
}

