import { eq as eq95, and as and76, isNotNull as isNotNull2 } from "drizzle-orm";
var BLING_SYNC_INTERVAL_MS = 60 * 60 * 1e3;
var META_SYNC_INTERVAL_MS = 30 * 60 * 1e3;
async function syncBlingForUser(userId, accessToken) {
  const endpoints = [
    { name: "produtos", path: "/produtos?pagina=1&limite=100" },
    { name: "pedidos", path: "/pedidos?pagina=1&limite=100" },
    { name: "contatos", path: "/contatos?pagina=1&limite=100" },
    { name: "estoques", path: "/estoques?pagina=1&limite=100" }
  ];
  for (const endpoint of endpoints) {
    try {
      const res = await fetch(
        `https://api.bling.com.br/Api/v3${endpoint.path}`,
        { headers: { Authorization: `Bearer ${accessToken}` } }
      );
      if (!res.ok) {
        console.warn(`[SyncAgent] Bling ${endpoint.name} userId=${userId} HTTP ${res.status}`);
        continue;
      }
      const data = await res.json();
      const count2 = Array.isArray(data?.data) ? data.data.length : 0;
      console.log(`[SyncAgent] Bling ${endpoint.name} userId=${userId} \u2014 ${count2} registros`);
    } catch (err) {
      console.error(`[SyncAgent] Bling ${endpoint.name} userId=${userId} erro:`, err);
    }
  }
}
async function syncMetaForUser(userId, accessToken) {
  const startedAt = Date.now();
  let totalCampaigns = 0;
  let updatedCampaigns = 0;
  let failedCampaigns = 0;
  let status = "success";
  let errorMessage;
  try {
    const accountsRes = await fetch(
      `https://graph.facebook.com/v18.0/me/adaccounts?fields=id,name,currency,account_status&access_token=${accessToken}`
    );
    if (!accountsRes.ok) throw new Error(`Accounts HTTP ${accountsRes.status}`);
    const accountsData = await accountsRes.json();
    const accounts = accountsData?.data ?? [];
    console.log(`[SyncAgent] Meta userId=${userId} \u2014 ${accounts.length} adaccounts`);
    for (const account of accounts) {
      try {
        const campaignsRes = await fetch(
          `https://graph.facebook.com/v18.0/${account.id}/campaigns?fields=id,name,status,objective,budget_remaining,daily_budget,lifetime_budget,start_time,stop_time,insights&access_token=${accessToken}`
        );
        if (!campaignsRes.ok) {
          failedCampaigns++;
          status = "partial";
          continue;
        }
        const campaignsData = await campaignsRes.json();
        const campaigns3 = campaignsData?.data ?? [];
        totalCampaigns += campaigns3.length;
        updatedCampaigns += campaigns3.length;
        console.log(`[SyncAgent] Meta account=${account.id} userId=${userId} \u2014 ${campaigns3.length} campanhas`);
      } catch (err) {
        failedCampaigns++;
        status = "partial";
        console.error(`[SyncAgent] Meta account=${account.id} userId=${userId} erro:`, err);
      }
    }
  } catch (err) {
    status = "failed";
    errorMessage = err instanceof Error ? err.message : String(err);
    console.error(`[SyncAgent] Meta userId=${userId} erro fatal:`, err);
  }
  try {
    const db = await getDb();
    if (db) {
      await db.insert(metaSyncHistory).values({
        userId,
        syncType: "full",
        totalCampaigns,
        updatedCampaigns,
        failedCampaigns,
        status,
        errorMessage: errorMessage ?? null,
        syncDuration: Date.now() - startedAt
      });
    }
  } catch (err) {
    console.error(`[SyncAgent] Falha ao gravar metaSyncHistory userId=${userId}:`, err);
  }
}
async function runBlingSync() {
  console.log("[SyncAgent] Iniciando sync Bling...");
  const db = await getDb();
  if (!db) {
    console.warn("[SyncAgent] Banco indispon\xEDvel \u2014 sync Bling abortado");
    return;
  }
  try {
    const tokens = await db.select().from(oauthTokens).where(and76(eq95(oauthTokens.plataforma, "bling"), eq95(oauthTokens.isActive, true), isNotNull2(oauthTokens.accessToken)));
    console.log(`[SyncAgent] Bling \u2014 ${tokens.length} usu\xE1rio(s) para sincronizar`);
    for (const token of tokens) {
      try {
        await syncBlingForUser(token.userId, token.accessToken);
      } catch (err) {
        console.error(`[SyncAgent] Bling userId=${token.userId} erro inesperado:`, err);
      }
    }
  } catch (err) {
    console.error("[SyncAgent] Bling erro ao buscar tokens:", err);
  }
  console.log("[SyncAgent] Sync Bling conclu\xEDdo.");
}
async function runMetaSync() {
  console.log("[SyncAgent] Iniciando sync Meta Ads...");
  const db = await getDb();
  if (!db) {
    console.warn("[SyncAgent] Banco indispon\xEDvel \u2014 sync Meta abortado");
    return;
  }
  try {
    const tokens = await db.select().from(oauthTokens).where(and76(eq95(oauthTokens.plataforma, "meta"), eq95(oauthTokens.isActive, true), isNotNull2(oauthTokens.accessToken)));
    console.log(`[SyncAgent] Meta \u2014 ${tokens.length} usu\xE1rio(s) para sincronizar`);
    for (const token of tokens) {
      try {
        await syncMetaForUser(token.userId, token.accessToken);
      } catch (err) {
        console.error(`[SyncAgent] Meta userId=${token.userId} erro inesperado:`, err);
      }
    }
  } catch (err) {
    console.error("[SyncAgent] Meta erro ao buscar tokens:", err);
  }
  console.log("[SyncAgent] Sync Meta Ads conclu\xEDdo.");
}
function startSyncAgent() {
  console.log("[SyncAgent] Agente iniciado (Bling=60min, Meta=30min)");
  runBlingSync().catch((err) => console.error("[SyncAgent] Erro na execu\xE7\xE3o inicial Bling:", err));
  runMetaSync().catch((err) => console.error("[SyncAgent] Erro na execu\xE7\xE3o inicial Meta:", err));
  const blingInterval = setInterval(() => {
    runBlingSync().catch((err) => console.error("[SyncAgent] Erro no interval Bling:", err));
  }, BLING_SYNC_INTERVAL_MS);
  const metaInterval = setInterval(() => {
    runMetaSync().catch((err) => console.error("[SyncAgent] Erro no interval Meta:", err));
  }, META_SYNC_INTERVAL_MS);
  return () => {
    clearInterval(blingInterval);
    clearInterval(metaInterval);
    console.log("[SyncAgent] Agente encerrado.");
  };
}

